/** All translations for zizhitongjian ch.046 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第046卷", literal: "Zizhi Tongjian, Volume 46.", idiomatic: "Zizhi Tongjian, Volume 46." },
  { zh: "【漢紀三十八】起柔兆困敦，盡閼逢涒灘，凡九年。", literal: "【Han Records 38】 From Rouzhao Kundun through Quefeng Youyan—in all, nine years.", idiomatic: "【Han Records 38】 From the first year of the Rouzhao cycle through the last year of the Quefeng cycle—nine years in all." },
  { zh: "春，正月，詔兗、豫、徐三州稟贍饑民。", literal: "In spring, the first month, an edict ordered Yan, Yu, and Xu commanderies to provision famine victims.", idiomatic: "In spring, in the first month, an edict ordered the commanderies of Yan, Yu, and Xu to supply grain to famine victims." },
  { zh: "上問司徒鮑昱：「何以消復旱災？", literal: "The emperor asked Minister of Education Bao Yu: \"How may the drought disaster be dispelled and restored?\"", idiomatic: "The emperor asked Minister of Education Bao Yu, \"How can we end this drought?\"" },
  { zh: "」對曰：「陛下始踐天位，雖有失得，未能致異。", literal: "\" He replied: \"Your Majesty has only just trodden Heaven's position; though there have been gains and losses, one could not yet bring forth anomalies.\"", idiomatic: "\" He answered, \"Your Majesty has only just ascended the throne. Though there have been slips, they could not yet have brought such portents.\"" },
  { zh: "臣前為汝南太守，典治楚事，系者千餘人，恐未能盡當其罪。", literal: "\"Your servant was formerly Administrator of Runan, in charge of Chu affairs; those imprisoned were more than a thousand—I fear they could not all have matched their crimes.\"", idiomatic: "\"When I was Administrator of Runan I handled the Chu affair. More than a thousand were imprisoned, and I fear many were not guilty as charged.\"" },
  { zh: "夫大獄一起，冤者過半。", literal: "\"When a great prison case arises, those wronged exceed half.\"", idiomatic: "\"Whenever a great criminal case is opened, more than half the accused are innocent.\"" },
  { zh: "又，諸徙者骨肉離分，孤魂不祀。", literal: "\"Moreover, all those exiled had flesh and bone torn apart; lone souls went without sacrifice.\"", idiomatic: "\"Moreover, the exiles were torn from their kin, and their lonely shades go unhonored.\"" },
  { zh: "宜一切還諸徙家。", literal: "\"It is fitting to restore all exiled households at once.\"", idiomatic: "\"You should bring every exiled household home.\"" },
  { zh: "蠲除禁錮，使死生獲所，則和氣可致。", literal: "\"Lift prohibitions and confinement, let the living and dead each gain their place—then harmonious qi may be attained.\"", idiomatic: "\"Lift the bans on office and release the confined, so the living and the dead each find their place, and harmonious qi will return.\"" },
  { zh: "」帝納其言。", literal: "\" The emperor adopted his words.", idiomatic: "\" The emperor accepted his counsel." },
  { zh: "校書郎楊終上疏曰：「間者北征匈奴，西開三十六國，百姓頻年服役，轉輸煩費；", literal: "Collator Yang Zhong memorialized: \"Recently there was northern campaign against the Xiongnu and western opening of the thirty-six states; the common people year after year served corvée, transport and supply vexed with expense;\"", idiomatic: "Collator Yang Zhong memorialized, \"Lately we have campaigned north against the Xiongnu and opened the thirty-six western states. The people have served year after year, drained by transport and supply;\"" },
  { zh: "愁困之民足以感動天地。", literal: "\"the people in grief and hardship suffice to move Heaven and Earth.\"", idiomatic: "\"a people so worn with grief can move Heaven and Earth itself.\"" },
  { zh: "陛下宜留念省察。", literal: "\"Your Majesty ought to keep this in mind and examine it.\"", idiomatic: "\"Your Majesty should take this to heart and look into it.\"" },
  { zh: "」帝下其章，第五倫亦同終議。", literal: "\" The emperor sent down his memorial; Fifth Lun likewise agreed with Zhong's proposal.", idiomatic: "\" The emperor circulated his memorial. Fifth Lun agreed with Zhong as well." },
  { zh: "牟融、飽昱皆以為：「孝子無改父之道。", literal: "Mou Rong and Bao Yu all held: \"The filial son does not alter his father's Way.\"", idiomatic: "Mou Rong and Bao Yu argued, \"A filial son does not change his father's course.\"" },
  { zh: "征伐匈奴，屯戍西域，先帝所建，不宜迥異。", literal: "\"Campaign against the Xiongnu and garrison the Western Regions were what the former emperor established—they ought not be abruptly changed.\"", idiomatic: "\"Campaigns against the Xiongnu and garrisons in the Western Regions were the late emperor's work. They should not be cast aside.\"" },
  { zh: "」終復上疏曰：「秦築長城，功役繁興；", literal: "\" Zhong again memorialized: \"Qin built the Long Wall and labor corvées flourished;\"", idiomatic: "\" Zhong memorialized again, \"Qin built the Long Wall and corvée multiplied;\"" },
  { zh: "胡亥不革，卒亡四海。", literal: "\"Huhai did not reform it, and in the end lost the four seas.\"", idiomatic: "\"Huhai would not reform it, and in the end lost the realm.\"" },
  { zh: "故孝元棄珠崖之郡，光武絕西域之國，不以介鱗易我衣裳。", literal: "\"Therefore Emperor Xiaoyuan abandoned the commandery of Zhuya; Emperor Guangwu cut off the western states—neither would trade our robes for scaly outsiders.\"", idiomatic: "\"Emperor Xiaoyuan gave up Zhuya; Emperor Guangwu cut ties with the Western Regions. Neither would trade our robes for the scales of barbarians.\"" },
  { zh: "魯文公毀泉台，《春秋》譏之曰：『先祖為之而己毀之，不如勿居而已，』以其無妨害於民也；", literal: "\"Duke Wen of Lu destroyed the Spring Terrace; the Spring and Autumn jeered at him, saying, 'The ancestors made it and you yourself destroy it—better not to dwell in it at all,' because it did no harm to the people;\"", idiomatic: "\"Duke Wen of Lu tore down the Spring Terrace. The Spring and Autumn jeers, 'Your ancestors built it and you destroy it—better never to have kept it at all,' for it harmed no one;\"" },
  { zh: "襄公作三軍，昭公捨之，君子大其復古，以為不捨則有害於民也。", literal: "\"Duke Xiang raised three armies; Duke Zhao set them aside—the noble man greatly praised his return to antiquity, holding that not setting them aside would harm the people.\"", idiomatic: "\"Duke Xiang raised three armies; Duke Zhao abolished them. The noble man praised his return to the old ways, for to keep them would have harmed the people.\"" },
  { zh: "今伊吾之役，樓蘭之屯兵久而未還，非天意也。", literal: "\"Now the labor at Yiyi and the garrison troops at Loulan long gone and not returned—this is not Heaven's intent.\"", idiomatic: "\"The labor at Yiyi and the garrison at Loulan have been away too long. This is not Heaven's will.\"" },
  { zh: "」帝從之。", literal: "\" The emperor followed this.", idiomatic: "\" The emperor agreed." },
  { zh: "丙寅，詔：「二千石勉勸農桑。", literal: "On the day bingyin, an edict: \"Those of two-thousand-dan rank shall strive to encourage farming and sericulture.\"", idiomatic: "On bingyin day an edict ran, \"Officials of two-thousand-dan rank must urge farming and sericulture.\"" },
  { zh: "罪非殊死，須秋案驗。", literal: "\"Crimes not of special death must await autumn for case verification.\"", idiomatic: "\"No one not sentenced to death shall be tried until autumn.\"" },
  { zh: "有司明慎選舉，進柔良，退貪猾，順時令，理冤獄。", literal: "\"The responsible offices shall clearly and carefully conduct selection and promotion—advance the gentle and good, retire the greedy and cunning, follow the seasons' commands, and settle wrongful prisons.\"", idiomatic: "\"Let every office choose and promote with care, advance the gentle and good, remove the greedy and cunning, follow the seasons, and right wrongful cases.\"" },
  { zh: "」是時承永平故事，吏政尚嚴切，尚書決事，率近於重。", literal: "\" At this time, inheriting Yongping precedent, clerical government still prized severity; the Masters of Writing in deciding affairs mostly leaned toward harshness.", idiomatic: "\" The court still followed Yongping ways. Officials prized severity, and the Masters of Writing in deciding cases leaned toward harshness." },
  { zh: "尚書沛國陳寵以帝新即位，宜改前世苛俗，乃上疏曰：「臣聞先王之政，賞不僭，刑不濫。", literal: "Master of Writing Chen Chong of Pei, because the emperor had newly taken the throne, held that one ought to change the former age's harsh customs; he memorialized: \"Your servant has heard that in the former kings' government rewards did not overstep and punishments did not overflow.\"", idiomatic: "Chen Chong of Pei, a Master of Writing, held that with a new emperor the harsh customs of the past age should change. He memorialized, \"I have heard that in the government of the ancient kings, rewards did not overstep and punishments did not overflow.\"" },
  { zh: "與其不得已，寧僭無濫。", literal: "\"Rather than what cannot be helped, better overstep than overflow.\"", idiomatic: "\"When one must choose, better to over-reward than to over-punish.\"" },
  { zh: "往者斷獄嚴明，所以威懲奸慝；", literal: "\"In the past, breaking prison cases with severity and clarity was to awe and chastise the treacherous and wicked;\"", idiomatic: "\"In the past, stern and clear judgment was meant to awe the wicked;\"" },
  { zh: "奸慝既平，必宜濟之以寬。", literal: "\"once the treacherous and wicked are settled, one must surely aid this with leniency.\"", idiomatic: "\"once the wicked are subdued, leniency must follow.\"" },
  { zh: "陛下即位，率由此義，數詔群僚，弘崇晏晏，而有司未悉奉承，猶尚深刻。", literal: "\"Your Majesty upon taking the throne has followed this principle throughout, repeatedly edicting the host of ministers to enlarge and honor ease—yet the responsible offices have not fully received and followed, and still prize severity.\"", idiomatic: "\"Since Your Majesty's accession you have followed this principle, again and again urging the ministers toward ease. Yet the offices have not fully obeyed and still prize severity.\"" },
  { zh: "斷獄者急於篣格酷烈之痛，執憲者煩於詆欺放濫之文，或因公行私，逞縱威福。", literal: "\"Those who break cases hurry after bamboo-rack and cruel pain; those who wield law are vexed by slander, deception, and reckless writings—or they use public office to pursue private ends and indulge their power and favor.\"", idiomatic: "\"Judges rush to rack and torment. Law officers drown in slander and reckless writs. Some use public office for private ends and abuse their power.\"" },
  { zh: "夫為政猶張琴瑟，大弦急者小弦絕。", literal: "\"To govern is like stretching zither and lute—when the great strings are tight, the small strings break.\"", idiomatic: "\"Government is like tuning a zither: when the great strings are too tight, the small strings snap.\"" },
  { zh: "陛下宜隆先王之道，蕩滌煩苛之法，輕薄棰楚以濟群生，全廣至德以奉天心。", literal: "\"Your Majesty ought to exalt the former kings' Way, wash away vexing and harsh laws, lighten the bamboo and bastinado to aid all living beings, and wholly extend utmost virtue to serve Heaven's heart.\"", idiomatic: "\"Your Majesty should exalt the Way of the ancient kings, wash away vexing laws, lighten the rod and lash to succor the people, and extend utmost virtue to answer Heaven's heart.\"" },
  { zh: "」帝深納寵言，每事務於寬厚。", literal: "\" The emperor deeply adopted Chong's words; in every affair he strove for lenience and breadth.", idiomatic: "\" The emperor took Chong's words deeply to heart and in every matter strove for leniency." },
  { zh: "酒泉太守段彭等兵會柳中，擊車師，攻交河城，斬首三千八百級，獲生口三千餘人。", literal: "Administrator of Jiuquan Duan Peng and others' troops joined at Liuzhong, struck the Cheshi, attacked Jiaohe city, cut heads to the level of three thousand eight hundred, and captured living mouths more than three thousand.", idiomatic: "Administrator of Jiuquan Duan Peng and others joined forces at Liuzhong, attacked the Cheshi, stormed Jiaohe city, took three thousand eight hundred heads, and captured more than three thousand alive." },
  { zh: "北匈奴驚走，車師復降。", literal: "The Northern Xiongnu fled in alarm; the Cheshi again submitted.", idiomatic: "The Northern Xiongnu fled in alarm, and the Cheshi submitted again." },
  { zh: "會關寵已歿，謁者王蒙等欲引兵還；", literal: "It happened that Guan Chong had already died; the Herald Wang Meng and others wished to lead the army back;", idiomatic: "Guan Chong had died, and Herald Wang Meng and the others meant to withdraw the army;" },
  { zh: "耿恭軍吏范羌，時在軍中，固請迎恭。", literal: "Geng Gong's army clerk Fan Qiang, then in the army, firmly requested to go welcome Gong.", idiomatic: "Fan Qiang, a clerk in Geng Gong's army, was in camp and pleaded hard to go bring Gong back." },
  { zh: "諸將不敢前，乃分兵二千人與羌，從山北迎恭，遇大雪丈餘，軍僅能至。", literal: "The generals dared not advance; they then divided two thousand troops to give Qiang, who from the mountain's north welcomed Gong—they met great snow more than a zhang deep, and the army barely could arrive.", idiomatic: "The generals dared not go forward. They gave Qiang two thousand men. He came round the mountain's north to meet Gong through snow more than ten feet deep, and the column barely made it." },
  { zh: "城中夜聞兵馬聲，以為虜來，大驚。", literal: "In the city by night they heard the sound of soldiers and horses, thought the foe had come, and were greatly alarmed.", idiomatic: "That night the city heard soldiers and horses and thought the enemy had come. All were terrified." },
  { zh: "羌遙呼曰：「我范羌也，漢遣軍迎校尉耳。", literal: "Qiang called from afar: \"I am Fan Qiang! Han has sent troops to welcome the colonel!\"", idiomatic: "Qiang shouted from afar, \"I am Fan Qiang! Han has sent troops to welcome the colonel!\"" },
  { zh: "」城中皆稱萬歲。", literal: "\" In the city all cried ten thousand years.", idiomatic: "\" The city erupted in cheers of ten thousand years." },
  { zh: "開門，共相持涕泣。", literal: "They opened the gate and, holding one another, wept.", idiomatic: "They opened the gates and wept in one another's arms." },
  { zh: "明日，遂相隨俱歸。", literal: "The next day they thereupon followed one another and all returned.", idiomatic: "The next day they set out together on the homeward march." },
  { zh: "虜兵追之，且戰且行。", literal: "The barbarian troops pursued them, fighting as they marched.", idiomatic: "The enemy pursued them, fighting as they marched." },
  { zh: "吏士素饑困，發疏勒時，尚有二十六人，隨路死沒，三月至玉門，唯餘十三人，衣屨穿決，形容枯槁。", literal: "The clerks and soldiers had long been hungry and worn; setting out from Shule there were still twenty-six men; along the road they died and were lost—after three months they reached Yumen, and only thirteen remained, clothes and shoes torn through, faces and forms withered.", idiomatic: "The men had long been starving. When they left Shule there were still twenty-six. Men died along the road. After three months they reached Yumen with only thirteen left, clothes and shoes in tatters, faces wasted to bone." },
  { zh: "中郎將鄭眾為恭已下洗沐，易衣冠，上疏奏：「恭以單兵守孤城，當匈奴數萬之眾，連月逾年，心力困盡，鑿山為井，煮弩為糧，前後殺傷丑虜數百千計，卒全忠勇，不為大漢恥，宜蒙顯爵，以厲將帥。", literal: "Palace Gentleman Zheng Zhong had Gong bathed and washed below, changed clothes and cap, and memorialized: \"Gong with lone troops held a solitary city against the Xiongnu host of tens of thousands, month upon month and year beyond year, heart and strength exhausted—he bored the mountain for a well and boiled crossbows for grain; before and after he killed and wounded the ugly foe by the hundreds and thousands in count, and in the end preserved loyalty and courage without shaming Great Han. He ought to receive a manifest rank to encourage generals and commanders.\"", idiomatic: "Palace Gentleman Zheng Zhong had Gong bathed and clothed anew, then memorialized, \"With a handful of men Gong held a lone city against tens of thousands of Xiongnu for more than a year until heart and strength were spent. He bored the mountain for water and boiled his crossbows for food. He killed barbarians by the hundreds and thousands, yet kept his loyalty and courage and brought no shame on Han. He deserves a high rank to hearten every commander.\"" },
  { zh: "」恭至雒陽，拜騎都尉。", literal: "\" Gong reached Luoyang and was appointed Colonel of the Exalted Cavalry.", idiomatic: "\" Gong reached Luoyang and was made Colonel of the Exalted Cavalry." },
  { zh: "詔悉罷戊、己校尉及都護官，征還班超。", literal: "An edict wholly abolished the Wuji and Jiyi colonels and the Protector-General posts, and summoned Ban Chao back.", idiomatic: "An edict abolished the Wuji and Jiyi colonels and the office of Protector-General and recalled Ban Chao." },
  { zh: "超將發還，疏勒舉國憂恐；", literal: "As Chao was about to set out on return, all Shule was anxious and afraid;", idiomatic: "As Chao prepared to withdraw, all Shule was stricken with fear;" },
  { zh: "其都尉黎弇曰：「漢使棄我，我必復為龜茲所滅耳，誠不忍見漢使去。", literal: "its Commandant Li Yi said: \"The Han envoy abandons us—we shall surely again be destroyed by Kucha. I truly cannot bear to see the Han envoy go.\"", idiomatic: "its commandant Li Yi said, \"If Han abandons us we shall be destroyed by Kucha again. I cannot bear to watch the envoy leave.\"" },
  { zh: "」因以刀自剄。", literal: "\" He thereupon with a blade cut his own throat.", idiomatic: "\" He took a blade and cut his own throat." },
  { zh: "超還至於窴，王侯以下皆號泣，曰：「依漢使如父母，誠不可去！", literal: "Chao returned as far as Yutian; kings, marquises, and below all wailed and wept, saying: \"We rely on the Han envoy as on father and mother—truly we cannot let him go!\"", idiomatic: "When Chao reached Yutian, kings and marquises down to the common folk wailed, \"We lean on the Han envoy as on father and mother. He truly cannot leave!\"" },
  { zh: "」互抱超馬腳不得行。", literal: "\" They clung to one another around Chao's horse's legs and could not advance.", idiomatic: "\" They clung to his horse's legs so that he could not move." },
  { zh: "超亦欲遂其本志，乃更還疏勒。", literal: "Chao also wished to fulfill his original intent and thereupon returned again to Shule.", idiomatic: "Chao too wished to keep his original purpose, and turned back to Shule." },
  { zh: "疏勒兩城已降龜茲，而與尉頭連兵。", literal: "Shule's two cities had already submitted to Kucha and joined arms with Weitou.", idiomatic: "Shule's two cities had already submitted to Kucha and allied with Weitou." },
  { zh: "超捕斬反者，擊破尉頭，殺六百餘人，疏勒復安。", literal: "Chao seized and beheaded the rebels, struck and broke Weitou, killed more than six hundred men, and Shule was again at peace.", idiomatic: "Chao seized and executed the rebels, defeated Weitou, killed more than six hundred men, and Shule was pacified again." },
  { zh: "甲寅，山陽、山平地震。", literal: "On the day jiayin, Shanyang and Shanping suffered earthquake.", idiomatic: "On jiayin day earthquakes struck Shanyang and Shanping." },
  { zh: "東平王蒼上便宜三事。", literal: "The Prince of Dongping, Cang, submitted three timely proposals.", idiomatic: "Prince of Dongping Cang submitted three timely proposals." },
  { zh: "帝報書曰：「間吏民奏事亦有此言，但明智淺短，或謂倘是，復慮為非，不知所定。", literal: "The emperor replied in writing: \"Recently when clerks and people submitted matters there was also this talk—but wisdom shallow and short, sometimes one thought perhaps it was so, then again feared it was not, and did not know what to fix on.\"", idiomatic: "The emperor wrote back, \"Lately officials and commoners who submitted memorials have said the same, but my judgment is shallow. I thought perhaps they were right, then feared they were wrong, and could not decide.\"" },
  { zh: "得王深策，恢然意解；", literal: "\"Receiving the prince's deep stratagem, my mind opened with relief;\"", idiomatic: "\"Your deep counsel has cleared my mind;\"" },
  { zh: "思惟嘉謀，以次奉行。", literal: "\"I will ponder fine plans and follow them in order.\"", idiomatic: "\"I will weigh your good plans and carry them out in turn.\"" },
  { zh: "特賜王錢五百萬。", literal: "\"I specially grant the prince five million cash.\"", idiomatic: "\"I grant you five million cash in special reward.\"" },
  { zh: "」後帝欲為原陵、顯節陵起縣邑，蒼上疏諫曰：「竊見光武皇帝躬履儉約之行，深睹始終之分，勤勤懇懇，以葬制為言；", literal: "\" Later the emperor wished to raise district and town for Yuanling and Xianjieling tombs; Cang memorialized in remonstrance: \"Your servant has seen that Emperor Guangwu personally trod the path of thrift, deeply perceived the division of beginning and end, and earnestly and repeatedly spoke on burial regulations;\"", idiomatic: "\" Later the emperor wished to establish counties and towns for the tombs Yuanling and Xianjieling. Cang memorialized in remonstrance, \"I have seen that Emperor Guangwu himself practiced thrift, understood beginning and end, and again and again urged restraint in burial;\"" },
  { zh: "孝明皇帝大孝無違，承奉遵行。", literal: "\"Emperor Xiaoming, greatly filial without disobedience, received and followed this in practice.\"", idiomatic: "\"Emperor Xiaoming, filial without breach, received and obeyed it.\"" },
  { zh: "謙德之美，於斯為盛。", literal: "\"The beauty of modest virtue—at this it was fullest.\"", idiomatic: "\"The beauty of modest virtue never shone brighter.\"" },
  { zh: "臣愚以園邑之興，始自強秦。", literal: "\"Your servant in folly holds that the rise of park-towns began with mighty Qin.\"", idiomatic: "\"I hold that park-towns began with mighty Qin.\"" },
  { zh: "古者丘隴且不欲其著明，豈況築郭邑、建都郛哉！", literal: "\"In antiquity even mounds and ridges were not wished to stand out clearly—how much less building walled towns and establishing outer cities!\"", idiomatic: "\"In antiquity even a mound was not meant to stand out. How much less to build walled towns and outer cities!\"" },
  { zh: "上違先帝聖心，下造無益之功，虛費國用，動搖百姓，非所以致和氣、祈豐年也。", literal: "\"Above it violates the former emperors' sage hearts; below it creates work without benefit, emptily spends state funds, and shakes the hundred surnames—this is not the means to bring harmonious qi and pray for abundant years.\"", idiomatic: "\"Above it violates the sage hearts of the former emperors; below it wastes labor, empties the treasury, and shakes the people. This is no way to summon harmonious qi or pray for a good harvest.\"" },
  { zh: "陛下履有虞之至性，追祖檷之深思，臣蒼誠傷二帝純德之美不暢於無窮也。", literal: "\"Your Majesty treads the utmost nature of Youyu, pursues the deep thought of the ancestral shrine—your servant Cang truly grieves that the pure virtue of the two emperors does not flow without end.\"", idiomatic: "\"Your Majesty walks in the utmost nature of the sage-king Shun and ponders the deep thought of the ancestral shrine. I grieve that the pure virtue of those two emperors may not shine without end.\"" },
  { zh: "」帝乃止。", literal: "\" The emperor thereupon stopped.", idiomatic: "\" The emperor desisted." },
  { zh: "自是朝廷每有疑政，輒驛使諮問，蒼悉心以對，皆見納用。", literal: "From this whenever the court had doubtful government, it at once sent relay envoys to consult; Cang with full heart answered, and all was seen and adopted.", idiomatic: "From then on, whenever the court faced a doubtful policy, it sent relay messengers to consult him. Cang answered with his whole heart, and his counsel was always adopted." },
  { zh: "秋，八月，庚寅，有星孛於天市。", literal: "In autumn, the eighth month, on the day gengyin, a broom star appeared in the Heavenly Market.", idiomatic: "In autumn, in the eighth month, on gengyin day, a broom star appeared in the Heavenly Market constellation." },
  { zh: "初，益州西部都尉廣漢鄭純，為政清潔，化行夷貊，君長感慕，皆奉珍內附；", literal: "Earlier, the Western Region Colonel of Yizhou Zheng Chun of Guanghan, his government clean and pure, his transformation reaching the Yi and Mo—chieftains were moved with admiration and all presented treasures and came within;", idiomatic: "Earlier, Western Region Colonel of Yizhou Zheng Chun of Guanghan governed with purity. His transforming influence reached the Yi and Mo. Their chieftains admired him and all brought tribute and submitted;" },
  { zh: "明帝為之置永昌郡，以純為太守。", literal: "Emperor Ming for this established Yongchang commandery and made Chun its administrator.", idiomatic: "Emperor Ming established Yongchang commandery for them and made Chun its administrator." },
  { zh: "純在官十年而卒，後人不能撫循夷人。", literal: "Chun held office ten years and died; later men could not soothe and guide the Yi.", idiomatic: "Chun held office ten years and died. Later men could not win the Yi." },
  { zh: "九月，哀牢王類牢殺守令反，攻博南。", literal: "In the ninth month, the Ailao king Leilao killed the administrator and magistrate and rebelled, attacking Bonan.", idiomatic: "In the ninth month the Ailao king Leilao killed the prefect and magistrate, rebelled, and attacked Bonan." },
  { zh: "阜陵王延數懷怨望，有告延與子男魴造逆謀者；", literal: "The Prince of Fuling, Yan, repeatedly harbored resentment and longing; someone reported that Yan and his son the heir Nanfang plotted rebellion;", idiomatic: "Prince of Fuling Yan had long nursed resentment. Someone reported that Yan and his heir Nanfang were plotting rebellion;" },
  { zh: "上不忍誅，冬十一月，貶延為阜陵侯，食一縣，不得與吏民通。", literal: "the emperor could not bear to execute him; in winter, the eleventh month, he degraded Yan to Marquis of Fuling, with sustenance from one county, and he might not communicate with clerks and people.", idiomatic: "the emperor could not bear to execute him. In winter, in the eleventh month, he degraded Yan to Marquis of Fuling with sustenance from one county and forbade him contact with officials or people." },
  { zh: "北匈奴皋林溫禺犢王將眾還居涿邪山，南單于與邊郡及烏桓共擊破之。", literal: "The Northern Xiongnu Golin Wenyu Du king led his host back to dwell at Zhuoye Mountain; the Southern Chanyu with border commanderies and the Wuhuan together struck and broke him.", idiomatic: "The Northern Xiongnu Golin Wenyu Du king led his people back to Zhuoye Mountain. The Southern Chanyu, with the frontier commanderies and the Wuhuan, defeated him together." },
  { zh: "是歲，南部大饑，詔稟給之。", literal: "This year the southern regions suffered great famine; an edict provisioned and supplied them.", idiomatic: "That year the south suffered great famine. An edict ordered grain supplied." },
  { zh: "春，三月，甲辰，罷伊吾盧屯兵，匈奴復遣兵守其地。", literal: "In spring, the third month, on the day jiachen, the Yiyi garrison troops were abolished; the Xiongnu again sent troops to hold that territory.", idiomatic: "In spring, in the third month, on jiachen day, the Yiyi garrison was withdrawn. The Xiongnu sent troops to hold the place again." },
  { zh: "永昌、越巂、益州三郡兵及昆明夷鹵承等，擊哀牢王類牢於博南，大破，斬之。", literal: "Troops of Yongchang, Yuesui, and Yizhou commanderies and the Kunming Yi Luchang and others struck the Ailao king Leilao at Bonan, broke him greatly, and beheaded him.", idiomatic: "Forces from Yongchang, Yuesui, and Yizhou and the Kunming Yi Luchang and others attacked the Ailao king Leilao at Bonan, routed him, and beheaded him." },
  { zh: "夏，四月，戊子，詔還坐楚、淮陽事徙者四百餘家。", literal: "In summer, the fourth month, on the day wuzi, an edict returned more than four hundred households exiled for the Chu and Huaiyang affairs.", idiomatic: "In summer, in the fourth month, on wuzi day, an edict brought home more than four hundred households exiled in the Chu and Huaiyang cases." },
  { zh: "上欲封爵諸舅，太后不聽。", literal: "The emperor wished to enfeoff and rank all his maternal uncles; the empress dowager would not listen.", idiomatic: "The emperor wished to enfeoff his maternal uncles. The empress dowager refused." },
  { zh: "會大旱，言事者以為不封外戚之故，有司請依舊典。", literal: "It happened that a great drought occurred; those who spoke on affairs held that it was because the outer kin were not enfeoffed; the responsible offices requested according to old precedent.", idiomatic: "A great drought followed. Memorialists said it was because the empress's kin had not been enfeoffed. The offices asked to follow the old precedent." },
  { zh: "太后詔曰：「凡言事者，皆欲媚朕以要福耳。", literal: "The empress dowager edicted: \"All who speak on affairs wish to flatter Us to seek fortune.\"", idiomatic: "The empress dowager edicted, \"Everyone who speaks on affairs only wants to flatter me for favor.\"" },
  { zh: "昔王氏五侯同日俱封，黃霧四塞，不聞澍雨之應。", literal: "\"In the past the Wang clan's five marquises on a single day were all enfeoffed—yellow mist blocked on four sides, and one did not hear the response of timely rain.\"", idiomatic: "\"When the Wang clan's five marquises were enfeoffed on one day, yellow mist closed in on every side and no timely rain followed.\"" },
  { zh: "夫外戚貴盛，鮮不傾覆；", literal: "\"When outer kin are noble and flourishing, few do not topple;\"", idiomatic: "\"When the empress's kin grow grand, few houses escape ruin;\"" },
  { zh: "故先帝防慎舅氏，不令在樞機之位，又言『我子不當與先帝子等』，今有司奈何欲以馬氏比陰氏乎！", literal: "\"therefore the former emperor guarded against the maternal clan, not letting them hold pivot-and-mechanism posts, and also said, 'My sons ought not be ranked with the former emperor's sons'—now how can the responsible offices wish to compare the Ma clan to the Yin clan!\"", idiomatic: "\"so the late emperor guarded against his wife's kin and would not place them at the heart of power, and said, 'My sons should not be ranked with the late emperor's sons.' How can the offices now compare the Ma to the Yin?\"" },
  { zh: "且陰衛尉，天下稱之，省中御者至門，出不及履，此蘧伯玉之敬也；", literal: "\"Moreover, Yin the Commandant of the Guards—the realm praised him; when the palace attendants reached his gate he went out without waiting for shoes—this was Qu Boyu's reverence;\"", idiomatic: "\"Yin, Commandant of the Guards, was praised throughout the realm. When palace attendants reached his gate he went out without waiting for his shoes—such was Qu Boyu's reverence;\"" },
  { zh: "新陽侯雖剛強，微失理，然有方略，據地談論，一朝無雙；", literal: "\"the Marquis of Xinyang, though strong and hard, slightly missed reason, yet had stratagem and plan—holding ground in discourse, in a morning without peer;\"", idiomatic: "\"the Marquis of Xinyang, though hard and sometimes unreasonable, had strategy. In debate on his own ground he had no peer in a morning;\"" },
  { zh: "原鹿貞侯，勇猛誠信；", literal: "\"the Marquis Zhen of Yuanlu, brave and fierce, sincere and faithful;\"", idiomatic: "\"the Marquis Zhen of Yuanlu, brave and true;\"" },
  { zh: "此三人者，天下選臣，豈可及哉！", literal: "\"these three men were chosen ministers of the realm—how could one reach them!\"", idiomatic: "\"these three were chosen ministers of the realm. Who could match them?\"" },
  { zh: "馬氏不及陰氏遠矣。", literal: "\"The Ma clan falls far short of the Yin clan.\"", idiomatic: "\"The Ma fall far short of the Yin.\"" },
  { zh: "吾不才，夙夜累息，常恐虧先後之法，有毛髮之罪吾不釋，言之不捨晝夜，而親屬犯之不止，治喪起墳，又不時覺，是吾言之不立而耳目之塞也。", literal: "\"We are without talent, night and day weary with sighs, constantly fearing to fall short of the laws of former and latter—if there is guilt the size of a hair We do not release it, speaking without leaving day or night, yet kin violate it without cease, managing funerals and raising tombs, and again not noticing in time—this is Our words not standing and Our ears and eyes blocked.\"", idiomatic: "\"I am without talent. Night and day I labor and sigh, fearing always to fall short of the laws left by my predecessors. The smallest fault I do not overlook. I speak without ceasing, day and night, yet my kin offend again and again, arranging funerals and raising tombs before I even know it. My words do not stand, and my ears and eyes are stopped.\"" },
  { zh: "吾為天下母，而身服大練，食不求甘，左右但著帛布，無香蕃之飾者，欲身率下也。", literal: "\"We are mother of the realm, yet personally wear great plain hemp, in food seek not sweetness, attendants only clothed in silk cloth without fragrant or elaborate adornment—wishing with Our body to lead those below.\"", idiomatic: "\"I am mother of the realm, yet I wear plain hemp, eat without seeking sweetness, and keep attendants in silk and cloth alone, without perfume or finery, wishing to lead those below by my own example.\"" },
  { zh: "以為外親見之，當傷心自敕，但笑言『太后素好儉』。", literal: "Thinking that when the external kin saw it they would be pained at heart and restrain themselves, but they only laughed and said, 'The empress dowager has always loved frugality.'", idiomatic: "She thought that when her maternal kin saw it they would be stung to conscience, but they only laughed and said, \"The empress dowager has always loved frugality.\"" },
  { zh: "前過濯龍門上，見外家問起居者，車如流水，馬如游龍，倉頭衣綠韝，領袖正白，顧視御者，不及遠矣。", literal: "Previously passing above the Dragon Bathing Gate, she saw those of the maternal clan inquiring after her health—carriages like flowing water, horses like swimming dragons, grooms in green quivers, collars and sleeves pure white—looking back at the imperial drivers, they fell not far short.", idiomatic: "Once, passing above the Dragon Bathing Gate, she saw her kin coming to inquire after her health—carriages like flowing water, horses like swimming dragons, grooms in green quivers with spotless white collars and sleeves—and when she looked back at the imperial train, her kin's display was not far behind." },
  { zh: "故不加譴怒，但絕歲用而已，冀以默愧其心，猶懈怠無憂國忘家之慮。", literal: "Therefore she did not add rebuke and anger but only cut off their yearly stipends, hoping to silently shame their hearts—they were still slack and without concern for the state or thought of forgetting the family.", idiomatic: "So she did not rebuke them outright but only cut off their yearly stipends, hoping to shame them in silence. They remained slack, with no care for the state or the family." },
  { zh: "知臣莫若君，況親屬乎！", literal: "No one knows a minister like the ruler—how much more so one's kin!", idiomatic: "No one knows a minister like his ruler—how much more one's own kin!" },
  { zh: "吾豈可上負先帝之旨，下虧先人之德，重襲西京敗亡之禍哉！", literal: "How could I above betray the late emperor's charge and below fail our ancestors' virtue, again inheriting the ruin of the Western Capital!", idiomatic: "How could I betray the late emperor's charge above and shame our ancestors' virtue below, and again bring on the ruin of the Western Capital!" },
  { zh: "」固不許。", literal: "\" She firmly did not permit it.", idiomatic: "\" She firmly refused." },
  { zh: "帝省詔悲歎，復重請曰：「漢興，舅氏之封侯，猶皇子之為王也。", literal: "The emperor read the edict and sighed in grief, again earnestly requesting: \"Since Han rose, enfeoffing maternal uncles as marquises is like making imperial princes kings.\"", idiomatic: "The emperor read the edict and sighed in grief, then pleaded again: \"Since Han rose, enfeoffing maternal uncles as marquises has been like making imperial princes kings.\"" },
  { zh: "太后誠存謙虛，奈何令臣獨不加恩三舅乎！", literal: "The empress dowager truly preserves humility—how could you let your servant alone not show favor to the three maternal uncles!", idiomatic: "The empress dowager is truly modest—yet how can you let me alone withhold favor from my three maternal uncles!" },
  { zh: "且衛尉年尊，兩校尉有大病，如令不諱，使臣長抱刻骨之恨。", literal: "Moreover the Commandant of the Guards is advanced in years, and the two colonels have grave illness—if, heaven forbid, something happened, it would make your servant bear lifelong hatred to the bone.", idiomatic: "Moreover the Commandant of the Guards is old, and the two colonels are gravely ill. If, heaven forbid, something happened, I would bear a lifelong grudge to the bone." },
  { zh: "宜及吉時，不可稽留。", literal: "One ought to seize the auspicious time and not delay.", idiomatic: "We ought to act while the time is auspicious and not delay." },
  { zh: "」太后報曰：「吾反覆念之，思令兩善，豈徒欲獲謙讓之名而使帝受不外施之嫌哉！", literal: "\" The empress dowager replied: \"I have thought it over again and again, wishing to make both sides good—how could I merely want to gain a name for modest yielding and let the emperor bear the suspicion of not extending favor outward!\"", idiomatic: "\" The empress dowager replied, \"I have turned it over again and again, seeking what is good for us both. Do you think I merely want a name for modesty and would let you bear the suspicion of withholding favor from your kin?\"" },
  { zh: "昔竇太后欲封王皇后之兄，丞相條侯言：『高祖約，無軍功不侯。", literal: "Formerly Empress Dowager Dou wished to enfeoff the Empress Wang's elder brother; Chancellor Marquis of Tiao said: 'The High Emperor's covenant: without military merit, no enfeoffment as marquis.", idiomatic: "Formerly Empress Dowager Dou wished to enfeoff Empress Wang's elder brother, but Chancellor Marquis of Tiao said, \"The High Emperor's covenant: without military merit, no marquisate.\"" },
  { zh: "』今馬氏無功於國，豈得與陰、郭中興之後等邪！", literal: "' Now the Ma clan has no merit to the state—how can they be ranked with the Yin and Guo, descendants of the restoration!\"", idiomatic: "\" The Ma clan has done nothing for the state. How can they be ranked with the Yin and Guo, the families of the restoration!\"" },
  { zh: "常觀富貴之家，祿位重疊，猶再實之木，其根必傷。", literal: "One often observes that in wealthy and noble houses, when salary and rank pile up, it is like a tree bearing fruit twice—its roots must be harmed.", idiomatic: "One often sees that in wealthy houses, when offices and salaries pile up, it is like a tree that fruits twice—its roots must suffer." },
  { zh: "且人所以願封侯者，欲上奉祭祀，不求溫飽耳；", literal: "Moreover the reason people wish to be enfeoffed as marquises is to above supply sacrifices—not to seek warmth and a full belly;", idiomatic: "Moreover men seek marquisates to supply ancestral sacrifices, not to seek comfort and full bellies;" },
  { zh: "今祭祀則受太官之賜，衣食則蒙御府餘資，斯豈不可足，而必當得一縣乎！", literal: "now for sacrifices they receive the Grand Provisioner's gifts, for food and clothing they enjoy the Imperial Treasury's surplus—is this not enough, yet they must have a whole county!", idiomatic: "now for sacrifices you receive the Grand Provisioner's gifts, and for food and clothing the Imperial Treasury's surplus—is that not enough? Must you have a whole county as well!" },
  { zh: "吾計之孰矣，勿有疑也。", literal: "I have calculated this thoroughly—do not doubt.", idiomatic: "I have thought this through thoroughly. Do not doubt it." },
  { zh: "夫至孝之行，安親為上。", literal: "In the conduct of utmost filial piety, securing the parent comes first.", idiomatic: "In utmost filial piety, securing one's parent comes first." },
  { zh: "今數遭變異，谷價數倍，憂惶晝夜，不安坐臥，而欲先營外家之封，違慈母之拳拳乎！", literal: "Now we repeatedly suffer strange omens, grain prices several times higher, anxious by day and night, unable to sit or lie in peace—yet you wish first to arrange enfeoffments for the maternal clan, violating a loving mother's earnest care!", idiomatic: "Now omens come again and again, grain costs several times more, and I am anxious day and night, unable to rest easy sitting or lying down—yet you wish first to arrange enfeoffments for your maternal kin, against a loving mother's earnest care!" },
  { zh: "吾素剛急，有胸中氣，不可不順也。", literal: "I have always been stern and quick-tempered, with breath in my chest—it must not be opposed.", idiomatic: "I have always been stern and quick-tempered, with fire in my breast—you must not oppose me." },
  { zh: "子之未冠，由於父母，已冠成人，則行子之志。", literal: "Before the son has capped, he is subject to his parents; once capped and adult, he follows the son's will.", idiomatic: "Before a son caps his hair he is subject to his parents; once capped and grown, he follows his own will." },
  { zh: "念帝，人君也；", literal: "Considering that the emperor is lord of men;", idiomatic: "I know you are lord of men;" },
  { zh: "吾以未逾三年之故，自吾家族，故得專之。", literal: "because the mourning period has not passed three years, within my own clan I can decide alone.", idiomatic: "but because the mourning period has not yet passed three years, within my own clan I may still decide alone." },
  { zh: "若陰陽調和，邊境清靜，然後行子之志；", literal: "if yin and yang are harmonious and the borders peaceful, then follow the son's will;", idiomatic: "when yin and yang are in harmony and the borders are quiet, then follow your own will;" },
  { zh: "吾但當含飴弄孫，不能復關政矣。", literal: "I should only hold candy and play with grandchildren—I cannot attend to government again.", idiomatic: "I should only hold candy and play with my grandchildren—I cannot attend to government again." },
  { zh: "」上乃止。", literal: "\" The emperor thereupon stopped.", idiomatic: "\" The emperor thereupon desisted." },
  { zh: "太后嘗詔三輔：諸馬昏親有屬托郡縣、干亂吏治者，以法聞。", literal: "The empress dowager once ordered the Three Adjuncts: any Ma kinsmen by marriage who entrust affairs to commanderies and counties or interfere with official governance—report according to law.", idiomatic: "The empress dowager once ordered the Three Adjuncts: any Ma kinsmen by marriage who pull strings with commanderies and counties or meddle in official business must be reported to the law." },
  { zh: "太夫人葬起墳微高，太后以為言，兄衛尉廖等即時減削。", literal: "When the Grand Lady's burial mound was raised slightly high, the empress dowager spoke of it, and her elder brother Commandant of the Guards Liao and the others at once reduced it.", idiomatic: "When their mother's burial mound was raised slightly high, the empress dowager spoke of it, and her elder brother Commandant of the Guards Liao and the others reduced it at once." },
  { zh: "其外親有謙素義行者，輒假借溫言，賞以財位；", literal: "Those among the external kin with modest conduct and righteous behavior—she would borrow gentle words and reward with wealth and position;", idiomatic: "Among her maternal kin, those of modest and righteous conduct she would address with gentle words and reward with wealth and office;" },
  { zh: "如有纖介，則先見嚴恪之色，然後加譴。", literal: "if there was the slightest fault, she first showed a stern and strict countenance, then added punishment.", idiomatic: "if there was the slightest fault, she first showed a stern face, then punished." },
  { zh: "其美車服、不尊法度者，便絕屬籍，遣歸田裡。", literal: "Those with fine carriages and dress who did not honor law and regulation—she at once struck them from the clan register and sent them back to their fields.", idiomatic: "Those with fine carriages and dress who scorned law and regulation she struck from the clan register at once and sent back to their fields." },
  { zh: "廣平、巨鹿、樂成王，車騎樸素，無金銀之飾，帝以白太后，即賜錢各五百萬。", literal: "The kings of Guangping, Julu, and Lecheng had plain carriages and horses without gold and silver ornament; when the emperor told the empress dowager, she at once granted each five million cash.", idiomatic: "The kings of Guangping, Julu, and Lecheng used plain carriages and horses without gold or silver ornament. When the emperor told the empress dowager, she at once granted each five million cash." },
  { zh: "於是內外從化，被服如一；", literal: "Thereupon inside and outside followed in transformation, dress all alike;", idiomatic: "Thereupon court and kin alike followed her example, dress becoming uniform;" },
  { zh: "諸家惶恐，倍於永平時。", literal: "all families were fearful, twice as much as in the Yongping era.", idiomatic: "and every household was twice as fearful as in the Yongping era." },
  { zh: "置織室，蠶於濯龍中，數往觀視，以為娛樂。", literal: "She set up a weaving chamber and raised silkworms in the Dragon Bathing quarter, often going to observe them as amusement.", idiomatic: "She set up a weaving chamber and raised silkworms in the Dragon Bathing quarter, often going to watch them for amusement." },
  { zh: "常與帝旦夕言道政事，及教授小王《論語》經書，述敘平生，雍和終日。", literal: "She often spoke of government affairs with the emperor morning and evening, and instructed the young kings in the Analects and classic texts, narrating her life, harmonious all day.", idiomatic: "She often discussed government with the emperor morning and evening, taught the young kings the Analects and the classics, recounted her life, and passed harmonious days." },
  { zh: "馬廖慮美業難終，上疏勸成德政曰：「昔元帝罷服官，成帝御浣衣，哀帝去樂府，然而侈費不息，至於衰亂者，百姓從行不從言也。", literal: "Ma Liao, fearing fine achievements would be hard to complete, submitted a memorial urging accomplished virtuous government, saying: \"Formerly Emperor Yuan abolished the garment office, Emperor Cheng personally handled washed clothes, Emperor Ai removed the music bureau—yet extravagant expenditure did not cease, until decay and disorder—because the common people follow conduct, not words.\"", idiomatic: "Ma Liao, fearing that fine achievements would be hard to sustain, submitted a memorial urging the completion of virtuous government: \"Formerly Emperor Yuan abolished the garment office, Emperor Cheng personally handled washed clothes, and Emperor Ai removed the music bureau—yet extravagance did not cease until decay and disorder came, because the people follow example, not words.\"" },
  { zh: "夫改政移風，必有其本。", literal: "To change government and shift custom there must be a root.", idiomatic: "To change government and shift custom there must be a root." },
  { zh: "《傳》曰：吳王好劍客，百姓多創瘢；", literal: "The Tradition says: The King of Wu loved swordsmen, and the common people had many scarred wounds;", idiomatic: "The Tradition says: The King of Wu loved swordsmen, and the common people bore many scars;" },
  { zh: "楚王好細腰，宮中多餓死。", literal: "the King of Chu loved slender waists, and in the palace many starved to death.", idiomatic: "the King of Chu loved slender waists, and many in the palace starved to death." },
  { zh: "』長安語曰：『城中好高結，四方高一尺；", literal: "' A Chang'an saying goes: 'When the city loves high buns, the four quarters are a foot higher;", idiomatic: "\" A Chang'an saying runs: \"When the city loves high topknots, the four quarters are a foot higher;\"" },
  { zh: "城中好廣眉，四方且半額；", literal: "when the city loves broad eyebrows, the four quarters have half their foreheads;", idiomatic: "when the city loves broad eyebrows, the four quarters paint half their foreheads;\"" },
  { zh: "城中好大袖，四方全匹帛。", literal: "when the city loves large sleeves, the four quarters use whole bolts of silk.'", idiomatic: "when the city loves large sleeves, the four quarters use whole bolts of silk.\"" },
  { zh: "』斯言如戲，有切事實。", literal: "' This speech is like jest, yet cuts to real fact.", idiomatic: "\" These words sound like jest, yet cut to the truth." },
  { zh: "前下制度未幾，後稍不行，雖或吏不奉法，良由慢起京師。", literal: "Not long after regulations were issued below, later they slightly were not followed—though sometimes clerks did not uphold the law, it was truly because slackness arose in the capital.", idiomatic: "Not long after regulations were issued, they were already slackly observed. Though some clerks failed to uphold the law, the real cause was that laxity began in the capital." },
  { zh: "今陛下素簡所安，發自聖性，誠令斯事一竟，則四海誦德，聲薰天地，神明可通，況於行令乎！", literal: "Now Your Majesty is by nature simple in what you rest in, arising from sage nature—if you truly let this matter be fully carried through, then the four seas will chant virtue, fame will fragrance heaven and earth, spirits may be reached—how much more executing orders!", idiomatic: "Your Majesty is by nature simple in what you love, and this arises from your sage nature. If you truly carry this matter through to the end, the four seas will chant your virtue, your fame will fragrance heaven and earth, and even the spirits may be reached—how much more will your orders be obeyed!" },
  { zh: "」太后深納之。", literal: "\" The empress dowager deeply accepted it.", idiomatic: "\" The empress dowager deeply accepted it." },
  { zh: "初，安夷縣吏略妻卑湳種羌人婦，吏為其夫所殺，安夷長宗延追之出塞。", literal: "Earlier, an Anyi county clerk seized a Beihan-clan Qiang man's wife; the clerk was killed by her husband; the Anyi chief Zongyan pursued him beyond the pass.", idiomatic: "Earlier an Anyi county clerk abducted a Beihan-clan Qiang man's wife. The clerk was killed by her husband, and the Anyi chief Zongyan pursued him beyond the frontier." },
  { zh: "種人恐見誅，遂共殺延而與勒姐、吾良二種相結為寇。", literal: "The tribesmen feared execution and together killed Yan and allied with the Lejie and Wuliang two tribes as raiders.", idiomatic: "The tribesmen, fearing punishment, together killed Yan and allied with the Lejie and Wuliang tribes to raid." },
  { zh: "於是燒當羌豪滇吾之子迷吾率諸種俱反，敗金城太守郝崇。", literal: "Thereupon the Shaodang Qiang chieftain Dianwu's son Miwu led all the tribes in revolt together and defeated Jin Cheng Administrator Hao Chong.", idiomatic: "Thereupon Miwu, son of the Shaodang Qiang chieftain Dianwu, led all the tribes in revolt and defeated Jin Cheng Administrator Hao Chong." },
  { zh: "詔以武威太守北地傅育為護羌校尉，自安夷徙居臨羌。", literal: "An edict made Wuwei Administrator Fu Yu of Beidi Colonel Protecting the Qiang, moving from Anyi to dwell at Linqiang.", idiomatic: "An edict appointed Wuwei Administrator Fu Yu of Beidi Colonel Protecting the Qiang and moved his headquarters from Anyi to Linqiang." },
  { zh: "迷吾又與封養種豪布橋等五萬餘人共寇隴西、漢陽。", literal: "Miwu again with the Fengyang tribe chieftain Buqiao and others, fifty thousand-plus men, jointly raided Longxi and Hanyang.", idiomatic: "Miwu again joined the Fengyang chieftain Buqiao and more than fifty thousand men in raiding Longxi and Hanyang." },
  { zh: "秋，八月，遣行車騎將軍馬防、長水校尉耿恭將北軍五校兵及諸郡射士三萬人擊之。", literal: "In autumn, the eighth month, acting Rapid-as-Tigers General Ma Fang and Chief of the Long River Geng Gong were dispatched leading the Northern Army's five-colonel troops and archers from various commanderies, thirty thousand men, to strike them.", idiomatic: "In autumn, in the eighth month, acting Rapid-as-Tigers General Ma Fang and Chief of the Long River Geng Gong were sent with the Northern Army's five-colonel troops and archers from the commanderies, thirty thousand men in all, to strike them." },
  { zh: "第五倫上疏曰：「臣愚以為貴戚可封侯以富之，不當任以職事。", literal: "Diwu Lun submitted a memorial: \"Your servant foolishly considers that noble kin may be enfeoffed as marquises to enrich them—they ought not be entrusted with official duties.", idiomatic: "Diwu Lun submitted a memorial: \"I foolishly think that noble kin may be enfeoffed as marquises to enrich them, but ought not be entrusted with official duties." },
  { zh: "何者？", literal: "Why?", idiomatic: "Why?" },
  { zh: "繩以法則傷恩，私以親則違憲。", literal: "Bound by law, affection is harmed; favored by kinship, the constitution is violated.", idiomatic: "Bound by law, affection is harmed; favored by kinship, the constitution is violated." },
  { zh: "伏聞馬防今當西征，臣以太后恩仁，陛下至孝，恐卒有纖介，難為意愛。", literal: "I have heard Ma Fang is now to campaign west; your servant, considering the empress dowager's gracious kindness and Your Majesty's utmost filial piety, fears that if there were the slightest incident, it would be hard to manage affection and love.", idiomatic: "I have heard that Ma Fang is now to campaign west. Considering the empress dowager's gracious kindness and Your Majesty's utmost filial piety, I fear that if the slightest incident occurred, it would be hard to balance affection and law." },
  { zh: "」帝不從。", literal: "\" The emperor did not follow.", idiomatic: "\" The emperor did not agree." },
  { zh: "馬防等軍到冀，布橋等圍南部都尉於臨洮，防進擊，破之，斬首虜四千餘人，遂解臨洮圍；", literal: "Ma Fang's army reached Ji; Buqiao and others besieged the Southern Colonel at Lintao; Fang advanced and struck, defeated them, beheaded and captured over four thousand, thereupon relieved the Lintao siege;", idiomatic: "Ma Fang's army reached Ji. Buqiao and others besieged the Southern Colonel at Lintao. Fang advanced, defeated them, beheaded and captured more than four thousand, and relieved the siege of Lintao;" },
  { zh: "其眾皆降，唯布橋等二萬餘人屯望曲谷不下。", literal: "their masses all submitted, only Buqiao and others, twenty thousand-plus, encamped at Wangqu Valley and would not come down.", idiomatic: "their followers all submitted, but Buqiao and more than twenty thousand others held Wangqu Valley and would not yield." },
  { zh: "十二月，戊寅，有星孛於紫宮。", literal: "In the twelfth month, on wuyin day, a broom star appeared in the Purple Palace constellation.", idiomatic: "In the twelfth month, on wuyin day, a broom star appeared in the Purple Palace constellation." },
  { zh: "帝納竇勳女為貴人，有寵。", literal: "The emperor took in Dou Xun's daughter as Noble Lady, and she had favor.", idiomatic: "The emperor took Dou Xun's daughter as Noble Lady, and she won favor." },
  { zh: "貴人母，即東海恭王女沘公主也。", literal: "The noble lady's mother was the Princess of Bi, daughter of the Prince of Donghai.", idiomatic: "The noble lady's mother was the Princess of Bi, daughter of the Prince of Donghai." },
  { zh: "第五倫上疏曰：「光武承王莽之餘，頗以嚴猛為政，後代因之，遂成風化；", literal: "Diwu Lun submitted a memorial: \"Emperor Guangwu, inheriting Wang Mang's residue, largely governed with stern severity; later generations followed this, and it became custom;", idiomatic: "Diwu Lun submitted a memorial: \"Emperor Guangwu, inheriting the aftermath of Wang Mang, largely governed with stern severity. Later generations followed this until it became custom;\"" },
  { zh: "郡國所舉，類多辦職俗吏，殊未有寬博之選以應上求者也。", literal: "what commanderies and states recommend are largely clerks skilled in office routine; there are scarcely broad and generous selections to answer what the throne seeks.", idiomatic: "what the commanderies and states recommend are largely clerks skilled in routine office work, with scarcely any broad and generous choices to meet what the throne seeks.\"" },
  { zh: "陳留令劉豫，冠軍令駟協，並以刻薄之姿，務為嚴苦，吏民愁怨，莫不疾之。", literal: "Chenliu Magistrate Liu Yu, Guanjun Magistrate Si Xie—both with harsh and mean dispositions, striving for stern severity—the officials and people were full of grief and resentment, all hated them.", idiomatic: "Chenliu Magistrate Liu Yu and Guanjun Magistrate Si Xie both had harsh and mean dispositions and strove for stern severity. Officials and commoners were full of grief and resentment and all hated them." },
  { zh: "而今之議者反以為能，違天心，失經義；", literal: "yet those who discuss today reverse and deem them able—this violates heaven's heart and loses canonical righteousness;", idiomatic: "Yet those who discuss affairs today reverse course and deem them able. This violates heaven's heart and loses canonical righteousness;" },
  { zh: "非徒應坐豫、協，亦宜譴舉者。", literal: "not only should Yu and Xie be punished—the recommenders should also be censured.", idiomatic: "not only should Yu and Xie be punished—the men who recommended them should also be censured." },
  { zh: "務進仁賢以任時政，不過數人，則風俗自化矣。", literal: "If one strives to advance humane and worthy men to bear current government, not more than a few, then custom will transform itself.", idiomatic: "If you strive to advance humane and worthy men to bear current government, not more than a few, custom will transform itself." },
  { zh: "臣嘗讀書記，知秦以酷急亡國，又目見王莽亦以苛法自滅，故勤勤懇懇，實在於此。", literal: "Your servant has read records and knows Qin perished through cruel haste, and has seen with my own eyes that Wang Mang also destroyed himself through harsh law—therefore earnest and urgent, it truly lies in this.", idiomatic: "I have read the records and know that Qin perished through cruel haste, and I have seen with my own eyes that Wang Mang destroyed himself through harsh law. That is why I plead so earnestly." },
  { zh: "又聞諸王、主、貴戚，驕奢逾制，京師尚然，何以示遠！", literal: "I also hear that the various kings, princesses, and noble kin are arrogant and extravagant beyond regulation—even the capital is thus—how can one show the distant!", idiomatic: "I also hear that kings, princesses, and noble kin are arrogant and extravagant beyond regulation. Even the capital is thus—how can we set an example for the distant regions!" },
  { zh: "故曰：『其身不正，雖令不行。", literal: "Therefore it is said: 'When one's person is not upright, though there be orders they are not followed.", idiomatic: "Therefore it is said, \"When the person is not upright, though there be orders they are not followed.\"" },
  { zh: "』以身教者從，以言教者訟。", literal: "' Those taught by the person follow; those taught by words dispute.", idiomatic: "\" Those taught by example follow; those taught by words dispute.\"" },
  { zh: "」上善之。", literal: "\" The emperor approved this.", idiomatic: "\" The emperor approved this." },
  { zh: "倫雖天性峭直，然常疾俗吏苛刻，論議每依寬厚雲。", literal: "Lun, though by nature stern and straight, constantly detested vulgar clerks' harshness; in discussion he always inclined toward generous lenience.", idiomatic: "Lun, though stern and straight by nature, constantly detested the harshness of vulgar clerks, and in discussion always inclined toward generous lenience." },
  { zh: "春，正月，己酉，宗祀明堂，登靈台，赦天下。", literal: "In spring, the first month, on jiyou day, the emperor sacrificed at the Bright Hall, ascended the Spirit Terrace, and amnestied the realm.", idiomatic: "In spring, in the first month, on jiyou day, the emperor sacrificed at the Bright Hall, ascended the Spirit Terrace, and amnestied the realm." },
  { zh: "馬防擊布橋，大破之，布橋將種人萬餘降，詔征防還。", literal: "Ma Fang attacked Buqiao and greatly defeated him; Buqiao led over ten thousand tribesmen to submit; an edict recalled Fang.", idiomatic: "Ma Fang attacked Buqiao and routed him. Buqiao led more than ten thousand tribesmen to submit. An edict recalled Fang." },
  { zh: "留耿恭擊諸未服者，斬首虜千餘人，勒姐、燒何等十三種數萬人，皆詣恭降。", literal: "Geng Gong was left to strike those not yet submitted, beheading and capturing over a thousand; the Lejie, Shaodang, and thirteen other tribes, tens of thousands, all came to Gong to submit.", idiomatic: "Geng Gong was left to strike those not yet submitted. He beheaded and captured more than a thousand. The Lejie, Shaodang, and thirteen other tribes, tens of thousands in all, came to Gong and submitted." },
  { zh: "恭嘗以言事忤馬防，監營謁者承旨，奏恭不憂軍事，坐征下獄，免官。", literal: "Gong had once spoken on affairs in opposition to Ma Fang; the supervising camp usher, following intent, memorialized that Gong did not care for military affairs—he was summoned, cast into prison, and dismissed from office.", idiomatic: "Gong had once spoken on affairs in opposition to Ma Fang. The supervising camp usher, following intent, memorialized that Gong did not care for military affairs. He was summoned, thrown into prison, and dismissed from office." },
  { zh: "三月，癸巳，立貴人竇氏為皇后。", literal: "In the third month, on guisi day, Noble Lady of the Dou clan was established as empress.", idiomatic: "In the third month, on guisi day, Noble Lady Dou was established as empress." },
  { zh: "初，顯宗之世，治虖沱、石臼河，從都慮至羊腸倉，欲令通漕。", literal: "Earlier, in Emperor Ming's reign, they worked on the Hutuo and Shijiu rivers from Dulu to Yangchang Granary, wishing to open transport by canal.", idiomatic: "Earlier, in Emperor Ming's reign, they worked on the Hutuo and Shijiu rivers from Dulu to Yangchang Granary, intending to open canal transport." },
  { zh: "太原吏民苦役，連年無成，死者不可勝算。", literal: "Taiyuan officials and people suffered from corvée labor; year after year it was not completed, the dead beyond counting.", idiomatic: "The officials and people of Taiyuan suffered under the corvée. Year after year the work was unfinished, and the dead were beyond counting." },
  { zh: "帝以郎中鄧訓為謁者，監領其事。", literal: "The emperor made Palace Gentleman Deng Xun an usher to supervise and lead the matter.", idiomatic: "The emperor made Palace Gentleman Deng Xun an usher to supervise the work." },
  { zh: "訓考量隱括，知其難成，具以上言。", literal: "Xun assessed and investigated, knew it was hard to complete, and fully reported upward.", idiomatic: "Xun surveyed and investigated, saw that completion was unlikely, and reported fully to the throne." },
  { zh: "夏，四月，己巳，詔罷其役，更用驢輦，歲省費億萬計，全活徒士數千人。", literal: "In summer, the fourth month, on jisi day, an edict halted the labor, changed to using donkey carts—yearly savings in the hundreds of millions, preserving the lives of several thousand laborers.", idiomatic: "In summer, in the fourth month, on jisi day, an edict halted the labor and changed to donkey carts instead. Yearly savings ran into the hundreds of millions, and several thousand laborers were spared." },
  { zh: "訓，禹之子也。", literal: "Xun was the son of Deng Yu.", idiomatic: "Xun was the son of Deng Yu." },
  { zh: "閏月，西域假司馬班超率疏勒、康居、於窴、拘彌兵一萬人攻姑墨石城，破之，斬首七百級。", literal: "In the intercalary month, Acting Major of the Western Regions Ban Chao led troops of Shule, Kangju, Yutian, and Jumi—ten thousand men—to attack the stone city of Gumo, broke it, and beheaded seven hundred.", idiomatic: "In the intercalary month, Acting Major of the Western Regions Ban Chao led ten thousand men from Shule, Kangju, Yutian, and Jumi against the stone city of Gumo, took it, and beheaded seven hundred." },
  { zh: "冬，十二月，丁酉，以馬防為車騎將軍。", literal: "In winter, the twelfth month, on dingyou day, Ma Fang was made Rapid-as-Tigers General.", idiomatic: "In winter, in the twelfth month, on dingyou day, Ma Fang was appointed Rapid-as-Tigers General." },
  { zh: "武陵漊中蠻反。", literal: "The Liuzhong tribes of Wuling rebelled.", idiomatic: "The Liuzhong tribes of Wuling rebelled." },
  { zh: "是歲，有司奏遣廣平王羨、巨鹿王恭、樂成王黨俱就國。", literal: "This year the responsible offices memorialized sending Kings of Guangping Xian, Julu Gong, and Lecheng Dang all to their states.", idiomatic: "That year the responsible offices memorialized that Kings Guangping Xian, Julu Gong, and Lecheng Dang should all go to their states." },
  { zh: "上性篤愛，不忍與諸王乖離，遂皆留京師。", literal: "The emperor was by nature deeply loving and could not bear separation from the various kings—all were kept in the capital.", idiomatic: "The emperor was deeply affectionate by nature and could not bear to part from his brothers, so all were kept in the capital." },
  { zh: "春，二月，庚寅，太尉牟融薨。", literal: "In spring, the second month, on gengyin day, Grand Commandant Mou Rong died.", idiomatic: "In spring, in the second month, on gengyin day, Grand Commandant Mou Rong died." },
  { zh: "夏，四月，戊子，立皇子慶為太子。", literal: "In summer, the fourth month, on wuzi day, the prince Qing was established as heir apparent.", idiomatic: "In summer, in the fourth month, on wuzi day, Prince Qing was established as heir apparent." },
  { zh: "己丑，徙巨鹿王恭為江陵王，汝南王暢為梁王，常山王昺為淮陽王。", literal: "On jichou day, King of Julu Gong was moved to be King of Jiangling, King of Runan Chang to King of Liang, King of Changshan Bing to King of Huaiyang.", idiomatic: "On jichou day, King of Julu Gong was moved to King of Jiangling, King of Runan Chang to King of Liang, and King of Changshan Bing to King of Huaiyang." },
  { zh: "辛卯，封皇子伉為千乘王，全為平春王。", literal: "On xinmao day, the princes Kang and Quan were enfeoffed as Kings of Qiansheng and Pingchun.", idiomatic: "On xinmao day, Princes Kang and Quan were enfeoffed as Kings of Qiansheng and Pingchun." },
  { zh: "有司連據舊典，請封諸舅。", literal: "The responsible offices repeatedly cited old precedent, requesting to enfeoff the maternal uncles.", idiomatic: "The responsible offices repeatedly cited old precedent and asked to enfeoff the maternal uncles." },
  { zh: "帝以天下豐稔，方垂無事，癸卯，遂封衛尉廖為順陽侯，車騎將軍防為穎陽侯，執金吾光為許侯。", literal: "The emperor, seeing the realm abundant and harvest full, with nothing impending, on guimao day enfeoffed Commandant of the Guards Liao as Marquis of Shunyang, Rapid-as-Tigers General Fang as Marquis of Yingyang, Chamberlain for the Credentials Guang as Marquis of Xu.", idiomatic: "The emperor, seeing the realm abundant and at peace, on guimao day enfeoffed Commandant of the Guards Liao as Marquis of Shunyang, Rapid-as-Tigers General Fang as Marquis of Yingyang, and Chamberlain for the Credentials Guang as Marquis of Xu." },
  { zh: "太后聞之曰：「吾少壯時，但慕竹帛，志不顧命。", literal: "The empress dowager heard and said: \"In my youth I only admired fame in bamboo and silk, my will heedless of life.", idiomatic: "When the empress dowager heard, she said, \"In my youth I cared only for fame in bamboo and silk, heedless of my life." },
  { zh: "今雖已老，猶戒之在得，故日夜惕厲，思自降損，冀乘此道，不負先帝。", literal: "Now though aged, I still guard against complacency in success—therefore day and night I am vigilant and strict, thinking to lower and reduce myself, hoping by this path not to fail the late emperor.", idiomatic: "Now, though I am old, I still guard against complacency in success. Day and night I am vigilant and strict, seeking to lower myself, hoping by this path not to fail the late emperor." },
  { zh: "所以化導兄弟，共同斯志，欲令瞑目之日，無所復恨，何意老志復不從哉！", literal: "For this I transformed and guided my brothers to share this aim, wishing that on the day I close my eyes there would be nothing more to regret—who thought in old age my will would again not be followed!\"", idiomatic: "For this I taught and guided my brothers to share this aim, wishing that when I close my eyes I would have nothing to regret. Who thought that in old age my will would again go unheeded!\"" },
  { zh: "萬年之日長恨矣！", literal: "On the day of ten thousand years there will be long regret!", idiomatic: "On the day I go to my grave there will be lasting regret!" },
  { zh: "」廖等並辭讓，願就關內侯，帝不許。", literal: "\" Liao and the others all declined and wished to take Marquis Within the Passes; the emperor did not permit it.", idiomatic: "\" Liao and the others all declined and asked for Marquis Within the Passes instead; the emperor refused." },
  { zh: "廖等不得已受封爵而上書辭位，帝許之。", literal: "Liao and the others, having no choice, accepted enfeoffment and memorialized to decline office; the emperor permitted it.", idiomatic: "Liao and the others had no choice but to accept the titles and then memorialized to resign their posts; the emperor agreed." },
  { zh: "五月，丙辰，防、廖、光皆以特進就第。", literal: "In the fifth month, on bingchen, Fang, Liao, and Guang all took Supernumerary Grand Counselor and retired to their mansions.", idiomatic: "In the fifth month, on bingchen day, Fang, Liao, and Guang all took honorary grand counselor rank and retired home." },
  { zh: "甲戌，以司徒鮑昱為太尉，南陽太守桓虞為司徒。", literal: "On jiaxu, made Grand Tutor Bao Yu Grand Commandant and Administrator of Nanyang Huan Yu Grand Tutor.", idiomatic: "On jiaxu day, Grand Tutor Bao Yu was made Grand Commandant and Administrator of Nanyang Huan Yu was made Grand Tutor." },
  { zh: "六月，癸丑，皇太后馬氏崩。", literal: "In the sixth month, on guichou, Empress Dowager of the Ma clan died.", idiomatic: "In the sixth month, on guichou day, Empress Dowager Ma died." },
  { zh: "帝既為太后所養，專以馬氏為外家，故賈貴人不登極位，賈氏親族無受寵榮者。", literal: "The emperor having been raised by the dowager, treated only the Ma clan as the maternal kin; therefore Honored Lady Jia did not ascend the supreme position, and Jia clan relatives received no favor or glory.", idiomatic: "The emperor had been raised by the dowager and treated only the Ma clan as his maternal kin; therefore Honored Lady Jia never became empress, and no Jia relatives received favor or honors." },
  { zh: "及太后崩，但加貴人王赤綬，安車一駟，永巷宮人二百，御府雜帛二萬匹，大司農黃金千斤，錢二千萬而已。", literal: "When the dowager died, he only added for the Honored Lady the king's red ribbon seal, one team of comfort carriage, two hundred Everlane palace women, twenty thousand bolts of miscellaneous silks from the imperial wardrobe, a thousand jin of gold from the Grand Minister of Agriculture, and twenty million cash—that was all.", idiomatic: "After the dowager died, he only gave the Honored Lady a red ribbon seal of kingly rank, one four-horse comfort carriage, two hundred Everlane palace attendants, twenty thousand bolts of palace silks, a thousand jin of gold from the treasury, and twenty million cash—and nothing more." },
  { zh: "秋，七月，壬戌，葬明德皇后。", literal: "In autumn, the seventh month, on renxu, the Bright Virtue Empress was buried.", idiomatic: "In autumn, in the seventh month, on renxu day, Bright Virtue Empress was buried." },
  { zh: "校書郎楊終建言：「宣帝博征群儒，論定《五經》於石渠閣。", literal: "Collator Yang Zhong submitted: \"Emperor Xuan broadly summoned the Confucian masters and settled the Five Classics at the Stone Canal Pavilion.\"", idiomatic: "Collator Yang Zhong memorialized, \"Emperor Xuan broadly summoned Confucian masters and fixed the Five Classics at the Stone Canal Pavilion.\"" },
  { zh: "方今天下少事，學者得成其業，而章句之徒，破環大體。", literal: "\"Now under heaven affairs are few; scholars can complete their studies, yet the chapter-and-clause crowd break and ruin the great substance.\"", idiomatic: "\"Now the realm is at peace and scholars can finish their studies, yet the chapter-and-clause pedants tear apart the larger meaning.\"" },
  { zh: "宜如石渠故事，永為後世則。", literal: "\"It is fitting to follow the Stone Canal precedent and make it an eternal model for later ages.\"", idiomatic: "\"We should follow the Stone Canal precedent and make it a lasting model for posterity.\"" },
  { zh: "」帝從之。", literal: "\" The emperor followed it.", idiomatic: "\" The emperor agreed." },
  { zh: "冬，十一月，壬戌，詔太常：「將、大夫、博士、郎官及諸儒會白虎觀，議《五經》同異。", literal: "In winter, the eleventh month, on renxu, an edict to the Minister of Ceremonies: \"Generals, grandees, erudites, gentleman officials, and all Confucians shall assemble at the White Tiger Hall to deliberate the agreements and differences of the Five Classics.\"", idiomatic: "In winter, in the eleventh month, on renxu day, an edict to the Minister of Ceremonies said, \"Generals, grandees, erudites, gentleman officials, and all scholars shall meet at the White Tiger Hall to debate the agreements and differences of the Five Classics.\"" },
  { zh: "」使五官中郎將魏應承製問，侍中淳於恭奏，帝親稱制臨決，作《白虎議奏》，名儒丁鴻、樓望、成封、桓郁、班固、賈逵及廣平王羨皆與焉。", literal: "\" He had Five-Office Center Commandant Wei Ying receive the imperial questions; Palace Attendant Chunyu Gong presented memorials; the emperor personally pronounced decisions on the spot and composed the \"White Tiger Discussion Memorial\"; famous scholars Ding Hong, Lou Wang, Cheng Feng, Huan Yu, Ban Gu, Jia Kui, and King Xian of Guangping all participated.", idiomatic: "\" Five-Office Center Commandant Wei Ying was ordered to pose the imperial questions; Palace Attendant Chunyu Gong presented replies; the emperor personally decided each point and produced the Baihu Discussion Memorial; renowned scholars Ding Hong, Lou Wang, Cheng Feng, Huan Yu, Ban Gu, Jia Kui, and King Xian of Guangping all took part." },
  { zh: "固，超之兄也。", literal: "Gu was Chao's elder brother.", idiomatic: "Gu was Ban Chao's elder brother." },
  { zh: "春，二月，庚辰朔，日有食之。", literal: "In spring, the second month, on the first day gengchen, there was an eclipse of the sun.", idiomatic: "In spring, in the second month, on the new moon of gengchen day, there was a solar eclipse." },
  { zh: "詔舉直言極諫。", literal: "An edict recommended men of frank speech and extreme remonstrance.", idiomatic: "An edict called for men who would speak frankly and remonstrate to the utmost." },
  { zh: "荊、豫諸郡兵討漊中蠻，破之。", literal: "Troops of the Jing and Yu commanderies attacked the Liaozhong barbarians and defeated them.", idiomatic: "Forces of the Jing and Yu commanderies attacked the Liaozhong barbarians and defeated them." },
  { zh: "夏，五月，辛亥，詔曰：「朕思遲直士，側席異聞，其先至者，各已發憤吐懣，略聞子大夫之志矣。", literal: "In summer, the fifth month, on xinhai, an edict said: \"We think of upright men slow to come; we sit sideways awaiting unusual reports—those who arrived first have each vented indignation and disgorged resentment; we have roughly heard your gentlemen's aims.\"", idiomatic: "In summer, in the fifth month, on xinhai day, an edict said, \"We long for upright men who have been slow to come; we sit alert for unusual counsel. Those who arrived first have each poured out their indignation; we have roughly heard your aims.\"" },
  { zh: "皆欲置於左右，顧問省納。", literal: "\"We wish to place them all at Our left and right for consultation and acceptance.\"", idiomatic: "\"We wish to keep them all at Our side for consultation and counsel.\"" },
  { zh: "建武詔書又曰：『堯試臣以職，不直以言語筆札。", literal: "\"The Jianwu edict also said: 'Yao tested his ministers by office, not directly by words and writing.'\"", idiomatic: "\"The Jianwu edict also said, 'Yao tested his ministers by their duties, not merely by words on paper.'\"" },
  { zh: "』今外官多曠，並可以補任。", literal: "\"'Now many outside offices stand vacant—all can be filled by appointment.'\"", idiomatic: "\"'Many provincial offices now stand vacant and may all be filled from among you.'\"" },
  { zh: "戊辰，太傅趙熹薨。", literal: "On wuchen, Grand Tutor Zhao Xi died.", idiomatic: "On wuchen day, Grand Tutor Zhao Xi died." },
  { zh: "班超欲遂平西域，上疏請兵曰：「臣竊見先帝欲開西域，故北擊匈奴，西使外國，善阜善、於窴即時向化，今拘彌、莎車、疏勒、月氏、烏孫、康居復願歸附，欲共並力，破滅龜茲，平通漢道。", literal: "Ban Chao wished to complete pacification of the Western Region and memorialized requesting troops, saying: \"Your servant has seen that the former emperor wished to open the Western Region; therefore he struck the Xiongnu in the north and sent envoys west to foreign states—Shanshan and Yutian at once turned to civilization; now Gumi, Shache, Shule, the Yuezhi, Wusun, and Kangju again wish to submit; they desire to join forces, destroy Qiuci, and clear the Han road.\"", idiomatic: "Ban Chao wished to finish pacifying the Western Region and memorialized for troops, saying, \"Your servant sees that the former emperor wished to open the Western Region; he struck the Xiongnu in the north and sent envoys west—Shanshan and Yutian submitted at once. Now Gumi, Shache, Shule, the Yuezhi, Wusun, and Kangju wish to submit again and join forces to destroy Qiuci and open the road to Han.\"" },
  { zh: "若得龜茲，則西域未服者百分之一耳。", literal: "\"If Qiuci is obtained, then of those in the Western Region not yet submitting it is only one percent.\"", idiomatic: "\"If we take Qiuci, the unsubmissive states of the Western Region will be one in a hundred.\"" },
  { zh: "前世議者皆曰：『取三十六國，號為斷匈奴右臂。", literal: "\"Former-age debaters all said: 'Take the thirty-six states—this is called cutting off the Xiongnu's right arm.'\"", idiomatic: "\"Former strategists all said, 'Take the thirty-six states and cut off the Xiongnu's right arm.'\"" },
  { zh: "』今西域諸國，自日之所入，莫不向化，大小欣欣，貢奉不絕，唯焉耆、龜茲獨未服從。", literal: "\"'Now the states of the Western Region, from where the sun enters, none do not turn to civilization; great and small are joyful; tribute and offerings never cease—only Yanqi and Qiuci alone have not yet submitted.'\"", idiomatic: "\"'Now the Western Region states from the sunset lands all submit; great and small rejoice and tribute never ceases—only Yanqi and Qiuci still refuse.'\"" },
  { zh: "臣前與官屬三十六人奉使絕域，備遭艱厄，自孤守疏勒，於今五載，胡夷情數，臣頗識之，問其城郭小大，皆言倚漢與依天等。", literal: "\"Your servant formerly with thirty-six officials and clerks received a mission to the uttermost region, fully suffered hardship and peril, and since holding Shule alone has now been five years; barbarian and Yi sentiments and numbers your servant knows fairly well—asking about their walled towns large and small, all say relying on Han is equal to relying on Heaven.\"", idiomatic: "\"Your servant once led thirty-six officials on a mission to the far west, suffered every hardship, and has held Shule alone for five years. I know the barbarians' temper and strength well; ask any town great or small and they will say relying on Han is like relying on Heaven.\"" },
  { zh: "以是效之，則蔥領可通，龜茲可伐。", literal: "\"By this effect, then the Onion Mountains can be opened and Qiuci can be attacked.\"", idiomatic: "\"Judging by this, the Onion Mountains can be opened and Qiuci can be attacked.\"" },
  { zh: "今宜拜龜茲侍子白霸為其國王，以步騎數百送之，與諸國連兵，歲月之間，龜茲可禽。", literal: "\"Now it is fitting to enfeoff Qiuci's hostage son Bai Ba as king of that state, send him with several hundred infantry and cavalry, join arms with the various states—in the space of months Qiuci can be captured.\"", idiomatic: "\"Now we should install Qiuci's hostage son Bai Ba as its king, escort him with several hundred foot and horse, and join the other states—within months Qiuci can be taken.\"" },
  { zh: "以夷狄攻夷狄，計之善者也。", literal: "\"Using barbarians and Yi to attack barbarians and Yi is the best of plans.\"", idiomatic: "\"Using barbarians to fight barbarians is the best plan.\"" },
  { zh: "臣見莎車、疏勒田地肥廣，草故饒衍，不比敦煌、善阜善間也，兵可不費中國而糧食自足。", literal: "\"Your servant sees Shache and Shule have fat, broad fields; grass and fodder are abundant—not like the region between Dunhuang and Shanshan; troops need not cost the central states and grain can be self-sufficient.\"", idiomatic: "\"Shache and Shule have rich, broad fields and abundant pasture—unlike the land between Dunhuang and Shanshan—so troops need not drain the central provinces and grain will suffice locally.\"" },
  { zh: "且姑墨、溫宿二王，特為龜茲所置，既非其種，更相厭苦，其勢必有降者。", literal: "\"Moreover the kings of Gumo and Wensu were specially installed by Qiuci; they are not of its stock; they mutually detest and suffer—their momentum surely must have those who surrender.\"", idiomatic: "\"Moreover the kings of Gumo and Wensu were installed by Qiuci and are not of its people; they hate each other bitterly—some are bound to defect.\"" },
  { zh: "若二國來降，則龜茲自破。", literal: "\"If the two states come to surrender, then Qiuci will break itself.\"", idiomatic: "\"If those two states surrender, Qiuci will collapse on its own.\"" },
  { zh: "願下臣章，參考行事，誠有萬分，死復何恨！", literal: "\"Your servant wishes Your Majesty to transmit his memorial, consult and act—if there is truly one ten-thousandth part of truth, what regret in death!\"", idiomatic: "\"I beg Your Majesty to transmit this memorial and act on it—if there is even one chance in ten thousand, what regret is death?\"" },
  { zh: "臣超區區特蒙神靈，竊冀未便僵仆，目見西域平定，陛下舉萬年之觴，薦勳祖廟，布大喜於天下。", literal: "\"Your servant Chao, petty and small, has specially received divine favor; he secretly hopes not yet to stiffen and fall, to see with his eyes the Western Region pacified, Your Majesty raising the cup of ten thousand years, presenting merit at the ancestral temple, and spreading great joy through all under heaven.\"", idiomatic: "\"Your petty servant Chao has been blessed beyond merit; I dare hope not to die yet, to see the Western Region pacified, Your Majesty raise the cup of long life, present our merit at the ancestral temple, and spread great joy through the realm.\"" },
  { zh: "」書奏，帝知其功可成，議欲給兵。", literal: "\" When the memorial was presented, the emperor knew his achievement could succeed and deliberated wishing to supply troops.", idiomatic: "\" When the memorial arrived, the emperor knew the plan could succeed and deliberated sending troops." },
  { zh: "平陵徐幹上疏，願奮身佐超，帝以幹為假司馬，將馳刑及義從千人就超。", literal: "Pingling's Xu Gan memorialized, wishing to throw himself forward to assist Chao; the emperor made Gan Acting Major and sent him with men relieved from punishment and righteous followers—a thousand men—to join Chao.", idiomatic: "Xu Gan of Pingling memorialized, offering to throw himself into service with Chao; the emperor made him Acting Major and sent a thousand men relieved from punishment and volunteer followers to join Chao." },
  { zh: "先是莎車以為漢兵不出，遂降於龜茲，而疏勒都尉番辰亦叛。", literal: "Earlier Shache, thinking Han troops would not come out, thereupon surrendered to Qiuci, and Commandant of Shule Fanchen also rebelled.", idiomatic: "Earlier Shache, thinking Han would not send troops, had surrendered to Qiuci, and Commandant of Shule Fanchen had also rebelled." },
  { zh: "會徐幹適至，超遂與幹擊番辰，大破之，斬首千餘級。", literal: "It happened that Xu Gan had just arrived; Chao thereupon with Gan attacked Fanchen, greatly defeated him, and beheaded more than a thousand.", idiomatic: "Just then Xu Gan arrived; Chao joined him in attacking Fanchen, routed him, and took more than a thousand heads." },
  { zh: "欲進攻龜茲，以烏孫兵強，宜因其力，乃上言：「烏孫大國，控弦十萬。", literal: "Wishing to advance and attack Qiuci, because Wusun's troops were strong it was fitting to use their strength; he thereupon submitted: \"Wusun is a great state controlling a hundred thousand bowstrings.\"", idiomatic: "Wishing to attack Qiuci, he held that Wusun's forces were strong and should be used, and memorialized, \"Wusun is a great power with a hundred thousand bowmen.\"" },
  { zh: "故武帝妻以公主，至孝宣帝卒得其用。", literal: "\"Therefore Emperor Wu married a princess to them; down to Emperor Xuan they finally obtained their use.\"", idiomatic: "\"Emperor Wu therefore married a princess to them, and by Emperor Xuan they were finally put to use.\"" },
  { zh: "今可遣使招慰，與共合力。", literal: "\"Now one can send envoys to summon and comfort them and join forces together.\"", idiomatic: "\"Now we can send envoys to win them over and join forces.\"" },
  { zh: "」帝納之。", literal: "\" The emperor accepted it.", idiomatic: "\" The emperor agreed." },
  { zh: "春。", literal: "Spring.", idiomatic: "Spring." },
  { zh: "二月，辛卯，琅邪孝王京薨。", literal: "In the second month, on xinmao, Filial King Jing of Langye died.", idiomatic: "In the second month, on xinmao day, Filial King Jing of Langye died." },
  { zh: "夏，六月，丙辰，太尉鮑昱薨。", literal: "In summer, the sixth month, on bingchen, Grand Commandant Bao Yu died.", idiomatic: "In summer, in the sixth month, on bingchen day, Grand Commandant Bao Yu died." },
  { zh: "辛未晦，日有食之。", literal: "On the last day xinwei, there was an eclipse of the sun.", idiomatic: "On the last day of the month, xinwei day, there was a solar eclipse." },
  { zh: "秋，七月，癸巳，以大司農鄧彪為太尉。", literal: "In autumn, the seventh month, on guisi, made Grand Minister of Agriculture Deng Biao Grand Commandant.", idiomatic: "In autumn, in the seventh month, on guisi day, Grand Minister of Agriculture Deng Biao was made Grand Commandant." },
  { zh: "武都太守廉范遷蜀郡太守。", literal: "Administrator of Wudu Lian Fan was transferred to Administrator of Shu.", idiomatic: "Administrator of Wudu Lian Fan was transferred to Administrator of Shu commandery." },
  { zh: "成都民物豐盛，邑宇逼側，舊制，禁民夜作以防火災，而更相隱蔽，燒者日屬。", literal: "Chengdu's people and goods were abundant; towns and houses were cramped; by old regulation night work by the people was forbidden to guard against fire disasters, yet they concealed it from one another, and burnings daily multiplied.", idiomatic: "Chengdu was rich and crowded; by old rule night work was forbidden to prevent fires, yet people hid it from one another and fires grew daily." },
  { zh: "范乃毀削先令，但嚴使儲水而已。", literal: "Fan thereupon destroyed and cut the former order, only strictly requiring stored water.", idiomatic: "Fan abolished the old rule and only required that water be stored." },
  { zh: "百姓以為便，歌之曰：「廉叔度，來何暮！", literal: "The common people thought it convenient and sang of it: \"Uncle Lian, how late you come!\"", idiomatic: "The people welcomed it and sang, \"Uncle Lian, why did you come so late!\"" },
  { zh: "不禁火，民安作。", literal: "\"Not forbidding fire, the people peacefully work.\"", idiomatic: "\"No fire ban—the people work in peace.\"" },
  { zh: "昔無襦，今五褲。", literal: "\"Formerly no coat; now five pairs of trousers.\"", idiomatic: "\"Once we had no coat; now we have five pairs of trousers.\"" },
  { zh: "帝以沛王等將入朝，遣謁者賜貂裘及太官食物、珍果，又使大鴻臚竇固持節郊迎。", literal: "The emperor, because the King of Pei and others were about to enter court, sent Gentlemen-in-Attendance to bestow sable furs and Grand Provisioner food and rare fruits, and also had Grand Herald Dou Gu hold the staff and meet them in the suburbs.", idiomatic: "Because the King of Pei and others were coming to court, the emperor sent attendants with sable furs, palace food, and rare fruits, and had Grand Herald Dou Gu meet them in the suburbs with credentials." },
  { zh: "帝親自循行邸第，豫設帷床，其錢帛、器物無不充備。", literal: "The emperor personally walked through their lodge quarters, set up curtains and couches in advance—their cash, silks, and implements were without exception fully provided.", idiomatic: "The emperor personally inspected their lodges, set out curtains and couches in advance, and saw that cash, silks, and goods were fully supplied." },
  { zh: "春，正月，沛王輔、濟南王康、東平王蒼、中山王焉、東海王政、琅邪王宇來朝。", literal: "In spring, the first month, King Fu of Pei, King Kang of Jinan, King Cang of Dongping, King Yan of Zhongshan, King Zheng of Donghai, and King Yu of Langye came to court.", idiomatic: "In spring, in the first month, King Fu of Pei, King Kang of Jinan, King Cang of Dongping, King Yan of Zhongshan, King Zheng of Donghai, and King Yu of Langye came to court." },
  { zh: "詔沛、濟南、東平、中山王贊拜不名，升殿乃拜，上親答之，所以寵光榮顯，加於前古。", literal: "An edict: the Kings of Pei, Jinan, Dongping, and Zhongshan in praise-bow were not named; ascending the hall then they bowed; the emperor personally replied—thereby favor, glory, and prominence beyond former antiquity.", idiomatic: "An edict granted the Kings of Pei, Jinan, Dongping, and Zhongshan the privilege of bowing without being named and of bowing only after ascending the hall; the emperor answered in person—honors surpassing any former age." },
  { zh: "每入宮，輒以輦迎，至省閣乃下，上為之興席改容，皇后親拜於內，皆鞠躬辭謝不自安。", literal: "Each time they entered the palace they were met by carriage; only at the inner gate did they descend; the emperor for them raised his mat and changed expression; the empress personally bowed within—all bowed with bent bodies and declined, not at ease.", idiomatic: "Whenever they entered the palace they were met by carriage and did not descend until the inner gate; the emperor rose and changed expression for them; the empress bowed to them within—all bowed and declined, ill at ease." },
  { zh: "三月，大鴻臚奏遣諸王歸國，帝特留東平王蒼於京師。", literal: "In the third month, the Grand Herald memorialized sending the various kings back to their states; the emperor specially kept King Cang of Dongping at the capital.", idiomatic: "In the third month, the Grand Herald memorialized to send the kings home; the emperor specially kept King Cang of Dongping at the capital." },
  { zh: "初，明德太后為帝納扶風宋楊二女為貴人，大貴人生太子慶。", literal: "Earlier Bright Virtue Dowager had the emperor take in two daughters of Song Yang of Fufeng as Honored Ladies; the Greater Honored Lady bore the crown prince Qing.", idiomatic: "Earlier Bright Virtue Dowager had the emperor take two daughters of Song Yang of Fufeng as Honored Ladies; the senior lady bore Crown Prince Qing." },
  { zh: "梁松弟竦有二女，亦為貴人，小貴人生皇子肇。", literal: "Liang Song's younger brother Song had two daughters who also became Honored Ladies; the Lesser Honored Lady bore the imperial son Zhao.", idiomatic: "Liang Song's younger brother Song had two daughters who also became Honored Ladies; the junior lady bore Prince Zhao." },
  { zh: "竇皇后無子，養肇為子。", literal: "Empress Dou had no son and raised Zhao as her son.", idiomatic: "Empress Dou had no son and adopted Zhao as her own." },
  { zh: "宋貴人有寵於馬太后，太后崩，竇皇后寵盛，與母沘陽公主謀陷宋氏，外令兄弟求其纖過，內使御者偵伺得失。", literal: "Honored Lady Song had favor with Empress Dowager Ma; when the dowager died, Empress Dou's favor flourished; with her mother Princess Biyang she plotted to trap the Song clan—outwardly ordering brothers to seek their minute faults, inwardly sending attendants to spy on gains and losses.", idiomatic: "Honored Lady Song had been favored by Empress Dowager Ma. After the dowager died, Empress Dou grew powerful; with her mother Princess Biyang she plotted against the Songs, ordering her brothers outside to hunt for petty faults and palace attendants inside to spy on their conduct." },
  { zh: "宋貴人病，思生兔，令家求之，因誣言欲為厭勝之術，由是太子出居承祿觀。", literal: "Honored Lady Song was ill, craved fresh rabbit, and ordered her family to seek it; they therefore slandered her as wishing to practice curse-suppression arts—thereby the crown prince moved out to dwell at Chenglu Watchtower.", idiomatic: "Honored Lady Song fell ill and craved fresh rabbit; her family sought one, and they slandered her as plotting curse magic—whereupon the crown prince was moved to Chenglu Watchtower." },
  { zh: "夏，六月，甲寅，詔曰：「皇太子有失惑無常之性，不可以奉宗廟。", literal: "In summer, the sixth month, on jiayin, an edict said: \"The crown prince has a nature of lost confusion and inconstancy—he cannot serve the ancestral temple.\"", idiomatic: "In summer, in the sixth month, on jiayin day, an edict said, \"The crown prince is unstable in mind and cannot serve the ancestral temple.\"" },
  { zh: "大義滅親，況降退乎！", literal: "\"Great principle destroys kin—how much more reduction and removal!\"", idiomatic: "\"Great principle requires sacrificing kin—how much more mere demotion!\"" },
  { zh: "今廢慶為清河王。", literal: "\"Now depose Qing as King of Qinghe.\"", idiomatic: "\"We now depose Qing as King of Qinghe.\"" },
  { zh: "皇子肇，保育皇后，承訓懷衽，今以肇為皇太子。", literal: "\"Imperial son Zhao, nurtured by the empress, received instruction at her breast—now make Zhao crown prince.\"", idiomatic: "\"Prince Zhao, raised by the empress and taught at her breast, is now made crown prince.\"" },
  { zh: "」遂出宋貴人姊妹置丙捨，使小黃門蔡倫案之。", literal: "\" Thereupon the Song Honored Ladies, sisters, were moved out to the third lodging; he sent Junior Palace Attendant Cai Lun to investigate them.", idiomatic: "\" The Song sisters were moved to the third lodging and Junior Palace Attendant Cai Lun was ordered to investigate them." },
  { zh: "二貴人皆飲藥自殺，父議郎楊免歸本郡。", literal: "Both Honored Ladies drank poison and killed themselves; their father Gentleman-of-Remonstrance Yang was dismissed and returned to his native commandery.", idiomatic: "Both Honored Ladies took poison and died; their father Remonstrance Officer Yang was dismissed and sent home." },
  { zh: "慶時雖幼，亦知避嫌畏禍，言不敢及宋氏；", literal: "Qing though young also knew to avoid suspicion and fear disaster, and in speech dared not touch on the Song clan;", idiomatic: "Though Qing was still young, he knew to avoid suspicion and never spoke of the Songs;" },
  { zh: "帝更憐之，敕皇后令衣服與太子齊等。", literal: "the emperor pitied him all the more and ordered the empress to make his clothes equal to the crown prince's.", idiomatic: "the emperor pitied him all the more and ordered the empress to give him clothing equal to the crown prince's." },
  { zh: "，太子亦親愛慶，入則共室，出則同輿。", literal: "the crown prince also loved Qing intimately—entering they shared a room, going out they shared a carriage.", idiomatic: "the crown prince also loved Qing dearly—they shared a room indoors and rode together outdoors." },
  { zh: "己未，徙廣平王羨為西平王。", literal: "On jiwei, moved King Xian of Guangping to King of Xiping.", idiomatic: "On jiwei day, King Xian of Guangping was moved to King of Xiping." },
  { zh: "秋，八月，飲酎畢，有司復奏遣東平王蒼歸國，帝乃許之，手詔賜蒼曰：「骨肉天性，誠不以遠近為親疏；", literal: "In autumn, the eighth month, when the communal wine-drinking was finished, the responsible offices again memorialized sending King Cang of Dongping back to his state; the emperor then permitted it and by hand-edict bestowed on Cang: \"Flesh-and-bone nature is innate—truly kinship is not made near or far by distance;", idiomatic: "In autumn, in the eighth month, after the communal wine rite the offices again memorialized to send King Cang of Dongping home; the emperor agreed and wrote him by hand, \"Flesh and bone share one nature; kinship is not measured by distance;" },
  { zh: "然數見顏色，情重昔時。", literal: "\"yet repeatedly seeing your countenance, affection weighs on former times.\"", idiomatic: "\"yet seeing you often has deepened my affection for days past.\"" },
  { zh: "念王久勞，思得還休，欲署大鴻臚奏，不忍下筆，顧授小黃門；", literal: "\"Thinking of the king's long toil, I desire you to return and rest; wishing to sign the Grand Herald's memorial, I cannot bear to put brush down and instead entrust a Junior Palace Attendant;\"", idiomatic: "\"Thinking of your long stay here, I wish you rest at home. I meant to sign the Grand Herald's memorial but could not bear to write and gave the task to a junior attendant instead;\"" },
  { zh: "中心戀戀，惻然不能言。", literal: "\"in the heart clinging and clinging, sorrowful and unable to speak.\"", idiomatic: "\"my heart clings to you, and I am too moved to say more.\"" },
  { zh: "」於是車駕祖送，流涕而訣；", literal: "\" Thereupon the imperial carriage escorted him at the road sacrifice, weeping in parting;", idiomatic: "\" Thereupon the emperor escorted him at the roadside sacrifice and wept at their farewell;" },
  { zh: "復賜乘輿服御，珍寶、輿馬，錢布以億萬計。", literal: "again bestowed imperial carriage robes and regalia, treasures, carriages and horses, cash and cloth reckoned in the hundreds of millions.", idiomatic: "then again gave him imperial carriage robes, treasures, carriages and horses, and cash and cloth reckoned in the tens of millions." },
  { zh: "九月，甲戌，帝幸偃師，東涉卷津，至河內，下詔曰：「車駕行秋稼，觀收穫，因涉郡界，皆精騎輕行，無它輜重。", literal: "In the ninth month, on jiaxu, the emperor favored Yanshi, crossed east over Juan Ford to Henei, and issued an edict: \"The imperial carriage travels the autumn grain, observing harvest—therefore crossing commandery borders—all are elite cavalry traveling light, no other baggage.", idiomatic: "In the ninth month, on jiaxu day, the emperor visited Yanshi, crossed Juan Ford east into Henei, and issued an edict, \"The imperial carriage is touring the autumn harvest. Crossing commandery borders, we travel with elite cavalry only, lightly and without other baggage.\"" },
  { zh: "不得輒修道橋，遠離城郭，遣吏逢迎，刺探起居，出入前後，以為煩擾。", literal: "\"Do not rashly repair roads and bridges, stay far from walled cities, send officials to meet and welcome, probe coming and going—before and behind, in and out—as annoyance and disturbance.\"", idiomatic: "\"Do not repair roads and bridges for us, stay far from cities, send officials to meet us, or spy on our comings and goings—that only harasses the people.\"" },
  { zh: "動務省約，但患不能脫粟瓢飲耳。", literal: "\"Actions must strive for austerity—only worry that We cannot drink hulled grain from a gourd.\"", idiomatic: "\"Be sparing in all you do—I only fear I cannot live on plain grain and gourd water.\"" },
  { zh: "」己酉，進幸鄴。", literal: "\" On jiyou, advanced to favor Ye.", idiomatic: "\" On jiyou day, he proceeded to Ye." },
  { zh: "辛卯，還宮。", literal: "On xinmao, returned to the palace.", idiomatic: "On xinmao day, he returned to the palace." },
  { zh: "冬，十月，癸丑，帝行幸長安，封蕭何末孫熊為酇侯。", literal: "In winter, the tenth month, on guichou, the emperor traveled to favor Chang'an and enfeoffed Xiao He's last descendant Xiong as Marquis of Zan.", idiomatic: "In winter, in the tenth month, on guichou day, the emperor traveled to Chang'an and enfeoffed Xiao He's last descendant Xiong as Marquis of Zan." },
  { zh: "進幸槐裡、岐山；", literal: "He advanced to favor Huaili and Mount Qi;", idiomatic: "He went on to Huaili and Mount Qi;" },
  { zh: "又幸長平，御池陽宮，東至高陵。", literal: "again favored Changping, attended at Chiyang Palace, and east to Gaoling.", idiomatic: "then to Changping, lodged at Chiyang Palace, and east as far as Gaoling." },
  { zh: "十二月，丁亥，還宮。", literal: "In the twelfth month, on dinghai, returned to the palace.", idiomatic: "In the twelfth month, on dinghai day, he returned to the palace." },
  { zh: "東平獻王蒼疾病，馳遣名醫、小黃門侍疾，使者冠蓋不絕於道。", literal: "Offering King Cang of Dongping fell ill; the emperor hurriedly sent famous physicians and Junior Palace Attendants to attend the illness; envoys with caps and canopies never ceased on the road.", idiomatic: "Offering King Cang of Dongping fell ill; the emperor hurriedly sent famous physicians and junior attendants to nurse him, and envoys with caps and canopies never ceased on the road." },
  { zh: "又置驛馬，千里傳問起居。", literal: "He also set relay horses to transmit inquiries of health and comfort a thousand li.", idiomatic: "He also set relay horses to carry inquiries of his health a thousand li at a time." },
  { zh: "春，正月，壬辰，王薨。", literal: "In spring, the first month, on renchen, the king died.", idiomatic: "In spring, in the first month, on renchen day, the king died." },
  { zh: "詔告中傅「封上王自建武以來章奏，並集覽焉。", literal: "An edict told the Palace Tutor: \"Seal and submit the king's memorials since Jianwu and assemble them for Our review.\"", idiomatic: "An edict told the palace tutor, \"Seal and submit all the king's memorials since Jianwu for Our review.\"" },
  { zh: "」遣大鴻臚持節監喪，令四姓小侯、諸國王、主悉會葬。", literal: "\" He sent the Grand Herald holding the staff to supervise the mourning and ordered the Four-Surname minor marquises, all state kings, and princesses to assemble for the burial.", idiomatic: "\" He sent the Grand Herald with credentials to supervise the funeral and ordered the Four-Surname minor marquises and all kings and princesses to attend the burial." },
  { zh: "夏，六月，北匈奴三木樓訾大人稽留斯等率三萬餘人款五原塞降。", literal: "In summer, the sixth month, Northern Xiongnu Sammu Louzi great men Jiliusi and others led more than thirty thousand men to knock sincerely at Wuyuan Pass and surrender.", idiomatic: "In summer, in the sixth month, Northern Xiongnu chieftains Jiliusi and others of the Sammu Louzi clan led more than thirty thousand men to present themselves at Wuyuan Pass and surrender." },
  { zh: "冬，十二月，甲午，上行幸陳留、梁國、淮陽、穎陽；", literal: "In winter, the twelfth month, on jiawu, the emperor traveled to favor Chenliu, Liang state, Huaiyang, and Yingyang;", idiomatic: "In winter, in the twelfth month, on jiawu day, the emperor traveled to Chenliu, Liang, Huaiyang, and Yingyang;" },
  { zh: "戊申，還宮。", literal: "On wushen, returned to the palace.", idiomatic: "On wushen day, he returned to the palace." },
  { zh: "太子肇之立也，梁氏私相慶；", literal: "When Crown Prince Zhao was established, the Liang clan privately congratulated one another;", idiomatic: "When Crown Prince Zhao was established as heir, the Liang clan privately congratulated one another;" },
  { zh: "諸竇聞而惡之。", literal: "the various Dou heard it and hated it.", idiomatic: "the various Dou clansmen heard of it and resented it." },
  { zh: "皇后欲專名外家，忌梁貴人姊妹，數譖之於帝，漸致疏嫌。", literal: "The empress wished to monopolize renown for her mother's kin, envied the Liang honorable ladies and their sisters, repeatedly slandered them to the emperor, and gradually brought about estrangement and suspicion.", idiomatic: "The empress wished to monopolize glory for her mother's kin, envied the Liang honorable ladies and their sisters, repeatedly slandered them to the emperor, and gradually brought about estrangement and suspicion." },
  { zh: "是歲，竇氏作飛書，陷梁竦以惡逆，竦遂死獄中，家屬徙九真，貴人姊妹以憂死。", literal: "This year the Dou clan composed flying letters and framed Liang Song with wicked rebellion; Song thereupon died in prison, his household was banished to Jiuzhen, and the honorable ladies' sisters died of grief.", idiomatic: "That year the Dou clan composed anonymous letters and framed Liang Song with treason; Song died in prison, his household was banished to Jiuzhen, and the honorable ladies' sisters died of grief." },
  { zh: "辭語連及梁松妻舞陰公主，坐徙新城。", literal: "The wording implicated Liang Song's wife, Princess Wuyin, who was punished by transfer to Xincheng.", idiomatic: "The wording implicated Liang Song's wife, Princess Wuyin, who was punished by banishment to Xincheng." },
  { zh: "順陽侯馬廖，謹篤自守，而性寬緩，不能教勒子弟，皆驕奢不謹。", literal: "Marquis Ma Liao of Shunyang was careful and sincere in self-restraint, yet by nature lenient and slack, unable to instruct and restrain his sons and younger brothers—they were all arrogant, extravagant, and unregulated.", idiomatic: "Marquis Ma Liao of Shunyang was careful and sincere in keeping himself in order, yet by nature lenient and slack and unable to discipline his sons and younger brothers, who were all arrogant, extravagant, and unrestrained." },
  { zh: "校書郎楊終與廖書，戒之曰；", literal: "Collator of Writings Yang Zhong wrote to Liao, admonishing him, saying:", idiomatic: "Collator of Writings Yang Zhong wrote to Liao to admonish him, saying," },
  { zh: "「君位地尊重，海內所望。", literal: "\"Your position and standing are honored; within the seas all look to you.", idiomatic: "\"Your position and standing are honored; the empire looks to you." },
  { zh: "黃門郎年幼，血氣方盛，既無長君退讓之風，而要結輕狡無行之客，縱而莫誨，視成任性，覽念前往，可為寒心！", literal: "The Gentlemen of the Yellow Gates are young, their blood and vigor just at full flood; they already lack an elder brother's manner of yielding, yet they seek and bind frivolous, cunning men without conduct; indulged and not taught, seen to completion they will follow their nature—reading this and thinking of what lies ahead, one can feel chilled at heart!\"", idiomatic: "The Gentlemen of the Yellow Gates are young and flush with vigor; they already lack an elder brother's manner of yielding, yet they court frivolous, cunning men of no character; indulged and untaught, they will follow their whims to the end—reading this and thinking of what lies ahead, one cannot but feel chilled at heart!\"" },
  { zh: "」廖不能從。", literal: "\" Liao could not follow it.", idiomatic: "\" Liao could not follow his advice." },
  { zh: "防、光兄弟資產巨億，大起第觀，彌亙街路，食客常數百人。", literal: "The brothers Fang and Guang had assets of hundreds of millions; they greatly raised mansions and towers stretching across the streets, with retainers often numbering several hundred.", idiomatic: "The brothers Fang and Guang had assets in the hundreds of millions; they built great mansions and towers that stretched across the streets, and their retainers often numbered several hundred." },
  { zh: "防又多牧馬畜，賦斂羌、胡。", literal: "Fang moreover pastured many horses and livestock and levied exactions on the Qiang and Hu.", idiomatic: "Fang also pastured vast herds and levied exactions on the Qiang and Hu." },
  { zh: "帝不喜之，數加譴敕，所以禁遏甚備。", literal: "The emperor disliked this and repeatedly added reprimands and edicts; the means of prohibition and restraint were very thorough.", idiomatic: "The emperor disliked this and repeatedly reprimanded them; his measures of prohibition and restraint were very thorough." },
  { zh: "由是權勢稍損，賓客亦衰。", literal: "Thereby their power and influence were somewhat diminished and their guests also declined.", idiomatic: "Thereby their power and influence waned somewhat, and their following of guests declined as well." },
  { zh: "廖子豫為步兵校尉，投書怨誹。", literal: "Liao's son Yu, Colonel of the Foot Soldiers, sent in a letter of resentment and slander.", idiomatic: "Liao's son Yu, Colonel of the Foot Soldiers, sent in a letter full of resentment and slander." },
  { zh: "於是有司並奏防、光兄弟奢侈逾僭，濁亂聖化，悉免就國。", literal: "Thereupon the responsible offices jointly memorialized that the brothers Fang and Guang were extravagant beyond their rank and defiled and confused the sage transformation; all were dismissed and sent to their states.", idiomatic: "Thereupon the responsible offices jointly memorialized that the brothers Fang and Guang were extravagant beyond their rank and corrupted the imperial teaching; all were dismissed and sent to their fiefs." },
  { zh: "臨上路，詔曰：「舅氏一門俱就國封，四時陵廟無助祭先後者，朕甚傷之，其令許侯思愆田廬，有司勿復請，以慰朕渭陽之情。", literal: "As they were about to set out, an edict said: \"The maternal kin's whole house together goes to their enfeoffed states; at the four seasons' mausoleum and temple there is no one to assist sacrifices in proper order—I am deeply pained. Order the Marquis of Xu to reflect on his faults at his fields and manor; the responsible offices must not again petition, to comfort my Weiyang feelings.\"", idiomatic: "As they were about to depart, an edict said, \"My mother's kin must all go to their fiefs; at the four seasons' mausoleum and temple no one will remain to assist the sacrifices in proper order—I am deeply grieved. Order the Marquis of Xu to reflect on his faults and remain at his fields and manor; the responsible offices must not petition again, to comfort my Weiyang feelings.\"" },
  { zh: "」光比防稍為謹密，故帝特留之，後復位特進。", literal: "\" Guang compared with Fang was somewhat more careful and close, therefore the emperor specially kept him; later he was again appointed Special Advance.", idiomatic: "\" Guang was somewhat more careful and discreet than Fang, so the emperor specially kept him at court; later he was again appointed Special Advance." },
  { zh: "豫隨廖歸國，考擊物故。", literal: "Yu followed Liao back to their state; under examination and beating he died.", idiomatic: "Yu followed Liao back to their fief; under examination and beating he died." },
  { zh: "後復有詔還廖京師。", literal: "Later there was again an edict returning Liao to the capital.", idiomatic: "Later an edict again recalled Liao to the capital." },
  { zh: "諸馬既得罪，竇氏益貴盛。", literal: "Once the various Ma had been punished, the Dou clan grew more honored and flourishing.", idiomatic: "Once the various Ma had been punished, the Dou clan grew ever more honored and powerful." },
  { zh: "皇后兄憲為侍中、虎賁中郎將，弟篤為黃門侍郎，並侍宮省，賞賜累積；", literal: "The empress's elder brother Xian was Attendant Within and Tiger-Gallant Center Commandant; her younger brother Du was Gentleman Attendant at the Yellow Gate; both attended the palace offices, with rewards and gifts accumulating;", idiomatic: "The empress's elder brother Xian was Attendant Within and Tiger-Gallant Center Commandant; her younger brother Du was Gentleman Attendant at the Yellow Gate; both attended the palace offices, and rewards and gifts piled up;" },
  { zh: "喜交通賓客。", literal: "they delighted in connecting with guests and retainers.", idiomatic: "and they delighted in cultivating guests and retainers." },
  { zh: "司空第五倫上疏曰：「臣伏見虎賁中郎將竇憲，椒房之親，典司禁兵，出入省闥，年盛志美，卑讓樂善，此誠其好士交結之方。", literal: "Minister of Works Diwu Lun submitted: \"Your servant humbly sees Tiger-Gallant Center Commandant Dou Xian, a relation of the pepper chambers, in charge of forbidden troops, entering and leaving the palace gates—his years flourishing, his will fine, humble, yielding, and delighting in good: this is truly his way of loving scholars and forming ties.", idiomatic: "Minister of Works Diwu Lun submitted, \"Your servant humbly observes Tiger-Gallant Center Commandant Dou Xian, a relation of the empress, in charge of the forbidden troops, entering and leaving the palace gates—his years are in their prime, his will is fine, and he is humble, yielding, and fond of good men: this is truly his way of loving scholars and forming ties." },
  { zh: "然諸出入貴戚者，類多瑕釁禁錮之人，尤少守約安貧之節。", literal: "Yet those who come and go among noble kin are mostly men with flaws and stains who have been confined and barred, and especially few have the integrity of keeping to covenant and resting content in poverty.", idiomatic: "Yet those who come and go among the noble kin are mostly men with blemished records who have been confined and barred, and especially few keep covenant and are content in poverty." },
  { zh: "士大夫無志之徒，更相販賣，雲集其門，蓋驕佚所從生也。", literal: "Scholar-officials without resolve trade with one another in turn and cloud-gather at his gate—this is surely where arrogance and dissipation are born.", idiomatic: "Scholar-officials without resolve trade favors with one another and swarm his gate—this is surely where arrogance and dissipation are born." },
  { zh: "三輔論議者至云：『以貴戚廢錮，當復以貴戚浣濯之，猶解酲當以酒也。", literal: "Discussants in the Three Metropolises even said: 'When a noble kin is dismissed and confined, he ought again to be rinsed clean by noble kin—as sobering from drunkenness ought to use wine.'", idiomatic: "Discussants in the Three Metropolises even said, 'When a noble kin is dismissed and confined, he ought again to be cleansed by noble kin—as sobering from drunkenness ought to use wine.'" },
  { zh: "』詖險趣勢之徒，誠不可親近。", literal: "' Men of perverse danger who rush toward power—truly they must not be approached.", idiomatic: "' Men of perverse cunning who rush toward power truly must not be approached." },
  { zh: "臣愚願陛下、中宮嚴敕憲等閉門自守，無妄交通士大夫，防其未萌，慮於無形，令憲永保福祿，君臣交歡，無纖介之隙，此臣之所至願也。", literal: "Your servant foolishly wishes that Your Majesty and the empress strictly order Xian and the others to shut their gates and keep themselves, not rashly to connect with scholar-officials, to guard what has not yet sprouted and take thought in what has no form, so that Xian may forever preserve blessing and rank, ruler and ministers mutually rejoicing without the slightest gap—this is what your servant most wishes.\"", idiomatic: "Your servant foolishly wishes that Your Majesty and the empress strictly order Xian and the others to shut their gates and keep to themselves, not rashly to traffic with scholar-officials, to guard what has not yet sprouted and take thought before anything takes shape, so that Xian may forever preserve blessing and rank and ruler and ministers may rejoice together without the slightest breach—this is what your servant most wishes.\"" },
  { zh: "憲恃宮掖聲勢，自王、主及陰、馬諸家，莫不畏憚。", literal: "Xian relied on the palace women's voice and power; from kings and princesses to the Yin and Ma households, none did not fear and dread him.", idiomatic: "Xian relied on the palace women's influence; from kings and princesses to the Yin and Ma households, none did not fear him." },
  { zh: "憲以賤直請奪泌水公主園田，主逼畏不敢計。", literal: "Xian at a low price requested to seize Princess Mishui's garden fields; the princess, pressed and in fear, did not dare reckon the account.", idiomatic: "Xian at a low price sought to seize Princess Mishui's garden fields; the princess, pressed and afraid, did not dare dispute the account." },
  { zh: "後帝出過園，指以問憲，憲陰喝不得對。", literal: "Later when the emperor went out and passed the garden he pointed and asked Xian; Xian in secret was shouted down and could not answer.", idiomatic: "Later when the emperor went out and passed the garden he pointed and asked Xian about it; Xian, silenced in secret, could not answer." },
  { zh: "後發覺，帝大怒，召憲切責曰：「深思前過奪主田園時，何用愈趙高指鹿為馬！", literal: "When it was later discovered the emperor was greatly angry, summoned Xian, and sharply reproached him: \"Think deeply on your former fault—when you seized the princess's garden fields, what need was there to go beyond Zhao Gao pointing to a deer and calling it a horse!", idiomatic: "When it was later discovered the emperor was furious, summoned Xian, and sharply reproached him, \"Think deeply on your former fault—when you seized the princess's garden fields, what need was there to go beyond Zhao Gao pointing to a deer and calling it a horse!" },
  { zh: "久念使人驚怖。", literal: "Long brooding on it makes one startled and terrified.", idiomatic: "Long brooding on it fills one with dread.\"" },
  { zh: "昔永平中，常令陰黨、陰博、鄧疊三人更相糾察，故諸豪戚莫敢犯法者。", literal: "In former times in the Yongping era they constantly had Yin Dang, Yin Bo, and Deng Die, three men, take turns investigating one another, therefore the various powerful kin did not dare break the law.", idiomatic: "In former times in the Yongping era they constantly had Yin Dang, Yin Bo, and Deng Die take turns investigating one another, so the various powerful kin did not dare break the law." },
  { zh: "今貴主尚見枉奪，何況小民哉！", literal: "Now even an honored princess still suffers wrongful seizure—how much more the common people!", idiomatic: "Now even an honored princess still suffers wrongful seizure—how much more the common people!" },
  { zh: "國家棄憲，如孤雛、腐鼠耳！", literal: "The state would abandon Xian like a lone chick or rotting rat!\"", idiomatic: "The state would abandon Xian like a lone chick or a rotting rat!\"" },
  { zh: "」憲大懼，皇后為毀服深謝，良久乃得解，使以田還主。", literal: "\" Xian was greatly afraid; the empress wore mourning dress and deeply apologized; only after long effort was he released, and he was made to return the fields to the princess.", idiomatic: "\" Xian was terrified; the empress wore mourning dress and apologized deeply; only after a long while was he released, and he was made to return the fields to the princess." },
  { zh: "雖不繩其罪，然亦不授以重任。", literal: "Though his crime was not prosecuted on the rope, yet he was also not entrusted with heavy duties.", idiomatic: "Though his crime was not prosecuted, he was also not entrusted with heavy duties." },
  { zh: "臣光曰：人臣之罪，莫大於欺罔，是以明君疾之。", literal: "Subject Guang said: Among a subject's crimes none is greater than deception—therefore the enlightened ruler hates it.", idiomatic: "Sima Guang remarks: Among a subject's crimes none is greater than deception; therefore the enlightened ruler hates it." },
  { zh: "孝章謂竇憲何異指鹿為馬，善矣；", literal: "Emperor Zhang's saying that Dou Xian was no different from pointing to a deer and calling it a horse was excellent;", idiomatic: "Emperor Zhang's saying that Dou Xian was no different from pointing to a deer and calling it a horse was excellent;" },
  { zh: "然卒不能罪憲，則奸臣安所懲哉！", literal: "yet in the end he could not punish Xian—then where are treacherous ministers to be disciplined!", idiomatic: "yet in the end he could not punish Xian—then where are treacherous ministers to be disciplined!" },
  { zh: "夫人主之於臣下，患在不知其奸，苟或知之而復赦之，則不若不知之為愈也。", literal: "Now the trouble for a lord of men toward subjects lies in not knowing their treachery; if he knows it and yet again pardons them, that is not as good as not knowing.", idiomatic: "For a ruler toward his subjects, the trouble lies in not knowing their treachery; if he knows it and yet pardons them again, that is not as good as not knowing." },
  { zh: "何以言之？", literal: "How is this said?", idiomatic: "Why is this so?" },
  { zh: "彼或為奸而上不之知，猶有所畏；", literal: "If they act treacherously and the ruler does not know them, they still have something to fear;", idiomatic: "If they act treacherously and the ruler does not know, they still have something to fear;" },
  { zh: "既知而不能討，彼知其不足畏也，則放縱而無所顧矣！", literal: "once he knows and yet cannot punish, they know he is not to be feared and then grow reckless with nothing to regard!", idiomatic: "once he knows and yet cannot punish, they know he is not to be feared and then grow reckless with nothing to hold them back!" },
  { zh: "是故知善而不能用，知惡而不能去，人主之深戒也。", literal: "Therefore to know the good yet be unable to employ it, to know the evil yet be unable to remove it—these are a lord of men's deep warnings.", idiomatic: "Therefore to know the good yet be unable to employ it, and to know the evil yet be unable to remove it—these are a ruler's deepest warnings." },
  { zh: "下邳周紆為雒陽令，下車，先問大姓主名；", literal: "Zhou Yu of Xiapi was Magistrate of Luoyang; on taking his carriage down he first asked the great clans' leading names;", idiomatic: "Zhou Yu of Xiapi was Magistrate of Luoyang; on taking office he first asked the leading names of the great clans;" },
  { zh: "吏數閭裡豪強以對。", literal: "the clerks listed neighborhood strongmen in reply.", idiomatic: "the clerks listed neighborhood strongmen in reply." },
  { zh: "紆厲聲怒曰：「本問貴戚若馬、竇等輩，豈能知此賣菜傭乎！", literal: "Yu in a harsh voice angrily said: \"I was asking about noble kin such as the Ma and Dou clans—how could I care to know these vegetable-selling hirelings!\"", idiomatic: "Yu said angrily in a harsh voice, \"I was asking about noble kin such as the Ma and Dou clans—how could I care to know these vegetable-selling hirelings!\"" },
  { zh: "」於是部吏望風旨，爭以激切為事，貴戚跼蹐，京師肅清。", literal: "\" Thereupon the department clerks caught his wind and intent and vied to make severity their business; the noble kin were cramped and constrained, and the capital was cleared.", idiomatic: "\" Thereupon the department clerks caught his intent and vied to act with severity; the noble kin were cramped and constrained, and the capital was cleared." },
  { zh: "竇篤夜至止奸亭，亭長霍延拔劍擬篤，肆詈恣口。", literal: "Dou Du came at night to Zhijian Pavilion; the pavilion chief Huo Yan drew his sword and aimed it at Du, reviling freely with an unrestrained mouth.", idiomatic: "Dou Du came at night to Zhijian Pavilion; the pavilion chief Huo Yan drew his sword and aimed it at Du, reviling him without restraint." },
  { zh: "篤以表聞，詔召司隸校尉、河南尹詣尚書譴問；", literal: "Du reported it upward; an edict summoned the Director of the Secretariat Censor and Administrator of Henan to the Masters of Writing for reprimand and inquiry;", idiomatic: "Du reported it upward; an edict summoned the Director of the Secretariat Censor and the Administrator of Henan to the Masters of Writing for reprimand and inquiry;" },
  { zh: "遣劍戟士收紆，送廷尉詔獄，數日，貰出之。", literal: "it sent sword-and-halberd soldiers to seize Yu and deliver him to the imperial prison under the Minister of Justice; after several days he was ransomed and released.", idiomatic: "it sent sword-and-halberd soldiers to seize Yu and deliver him to the imperial prison under the Minister of Justice; after several days he was ransomed and released." },
  { zh: "帝拜班超為將兵長史，以徐幹為軍司馬，別遣衛侯李邑護送烏孫使者。", literal: "The emperor appointed Ban Chao General's Staff Major and made Xu Gan Army Major, separately sending Defender Marquis Li Yi to escort the Wusun envoy.", idiomatic: "The emperor appointed Ban Chao General's Staff Major and made Xu Gan Army Major, and separately sent Defender Marquis Li Yi to escort the Wusun envoy." },
  { zh: "邑到於窴，值龜茲攻疏勒，恐懼不敢前，因上書陳西域之功不可成，又盛毀超：「擁愛妻，抱愛子，安樂外國，無內顧心。", literal: "When Yi reached Yutian, Kucha was attacking Shule; in fear he did not dare advance, and thereby submitted a memorial stating that achievements in the Western Regions could not be accomplished, and also greatly slandered Chao: \"He embraces his beloved wife and holds his beloved son, enjoying ease in a foreign land with no heart to look within.\"", idiomatic: "When Yi reached Yutian, Kucha was attacking Shule; in fear he did not dare advance and memorialized that achievements in the Western Regions could not be accomplished, and also greatly slandered Chao, saying, \"He embraces his beloved wife and holds his beloved son, enjoying ease in a foreign land with no heart to look homeward.\"" },
  { zh: "」超聞之歎曰：「身非曾參而有三至之讒，恐見疑於當時矣！", literal: "\" Chao heard it and sighed: \"Though my person is not Zeng Shen, yet there is thrice-repeated slander—I fear I will be suspected in my own time!\"", idiomatic: "\" Chao heard it and sighed, \"Though I am not Zeng Shen, yet there is thrice-repeated slander—I fear I will be suspected in my own time!\"" },
  { zh: "」遂去其妻。", literal: "\" He thereupon sent away his wife.", idiomatic: "\" He thereupon sent away his wife." },
  { zh: "帝知超忠，乃切責邑曰：「縱超擁愛妻，抱愛子，思歸之士千餘人，何能盡與超同心乎！", literal: "The emperor knew Chao was loyal and thereupon sharply reproached Yi: \"Even if Chao embraces his beloved wife and holds his beloved son, men longing to return number more than a thousand—how could they all be of one heart with Chao!\"", idiomatic: "The emperor knew Chao was loyal and sharply reproached Yi, \"Even if Chao embraces his beloved wife and holds his beloved son, men longing to return number more than a thousand—how could they all be of one heart with Chao!\"" },
  { zh: "」令邑詣超受節度，詔：「若邑任在外者，便留與從事。", literal: "\" He ordered Yi to go to Chao and accept his direction; an edict said: \"If Yi proves fit for duty abroad, then keep him with the Attending Clerk.\"", idiomatic: "\" He ordered Yi to go to Chao and accept his direction, with an edict, \"If Yi proves fit for duty abroad, keep him with the Attending Clerk.\"" },
  { zh: "」超即遣邑將烏孫侍子還京師。", literal: "\" Chao at once sent Yi to lead the Wusun hostage prince back to the capital.", idiomatic: "\" Chao at once sent Yi to lead the Wusun hostage prince back to the capital." },
  { zh: "徐幹謂超曰：「邑前親毀君，欲敗西域，今何不緣詔書留之，更遣它吏送侍子乎？", literal: "Xu Gan said to Chao: \"Yi earlier personally slandered you and wished to ruin the Western Regions—why not now use the edict's words to keep him and send another clerk to escort the hostage prince?\"", idiomatic: "Xu Gan said to Chao, \"Yi earlier slandered you in person and wished to ruin the Western Regions—why not now use the edict's words to keep him and send another clerk to escort the hostage prince?\"" },
  { zh: "」超曰：「是何言之陋也！", literal: "\" Chao said: \"How base are such words!\"", idiomatic: "\" Chao said, \"How base are such words!\"" },
  { zh: "以邑毀超，故今遣之。", literal: "Because Yi slandered Chao, therefore he is now sent away.", idiomatic: "Because Yi slandered Chao, I now send him away for that very reason." },
  { zh: "內省不疚，何恤人言！", literal: "Inward examination finds no fault—why worry over men's words!", idiomatic: "Inward examination finds no fault—why worry over men's words!" },
  { zh: "快意留之，非忠臣也。", literal: "To keep him to satisfy one's will is not the act of a loyal minister.\"", idiomatic: "To keep him merely to satisfy one's will is not the act of a loyal minister.\"" },
  { zh: "帝以侍中會稽鄭弘為大司農。", literal: "The emperor made Attendant Within Zheng Hong of Kuaiji Grand Minister of Agriculture.", idiomatic: "The emperor made Attendant Within Zheng Hong of Kuaiji Grand Minister of Agriculture." },
  { zh: "舊交趾七郡貢獻轉運，皆從東冶泛海而至，風波艱阻，沒溺相系。", literal: "Formerly the seven commanderies of Jiaozhi's tribute transport all went from Dongye by sea, and wind and waves were hard and obstructive, with drowning victims linked in succession.", idiomatic: "Formerly tribute transport from the seven Jiaozhi commanderies all went from Dongye by sea, where wind and waves were perilous and drownings followed one upon another." },
  { zh: "弘奏開零陵、桂陽嶠道，自是夷通，遂為常路。", literal: "Hong memorialized to open the mountain passes between Lingling and Guiyang; from this the barbarian lands were opened through and it became the regular route.", idiomatic: "Hong memorialized to open the mountain route between Lingling and Guiyang; from then the route was cleared and became the regular road." },
  { zh: "在職二年，所息省以億萬計。", literal: "In office two years, what he saved and reduced amounted to hundreds of millions.", idiomatic: "In two years in office, what he saved and reduced amounted to hundreds of millions." },
  { zh: "遭天下旱，邊方有警，民食不足，而帑藏殷積。", literal: "It happened that the realm suffered drought, the borderlands had alarms, the people's food was insufficient, yet the treasury stores were richly piled.", idiomatic: "When the realm suffered drought, the borderlands had alarms, and the people's food was insufficient, the treasury stores were nonetheless richly piled." },
  { zh: "弘又奏宜省貢獻，減徭費以利饑民；", literal: "Hong again memorialized that tribute should be reduced and corvée expenses cut to benefit the starving people;", idiomatic: "Hong again memorialized that tribute should be reduced and corvée expenses cut to benefit the starving people;" },
  { zh: "帝從之。", literal: "the emperor followed it.", idiomatic: "the emperor approved." },
  { zh: "春，閏正月，辛丑，濟陰悼王長薨。", literal: "In spring, in the intercalary first month, on xinchou, Prince Chang the Lamented of Jiyin died.", idiomatic: "In spring, in the intercalary first month, on xinchou day, Prince Chang the Lamented of Jiyin died." },
  { zh: "夏，四月，己卯，分東平國，封獻王子尚為任城王。", literal: "In summer, the fourth month, on jimao, the state of Dongping was divided and Prince Xian's son Shang was enfeoffed as Prince of Rencheng.", idiomatic: "In summer, in the fourth month, on jimao day, Dongping was divided and Prince Xian's son Shang was enfeoffed as Prince of Rencheng." },
  { zh: "六月，辛酉，沛獻王輔薨。", literal: "In the sixth month, on xinyou, Prince Fu the Exalted of Pei died.", idiomatic: "In the sixth month, on xinyou day, Prince Fu the Exalted of Pei died." },
  { zh: "陳事者多言「郡國貢舉，率非功次，故守職益懈而吏事浸疏，咎在州郡。", literal: "Those presenting matters many times said: \"Commandery and state recommendations and selections mostly do not follow merit and order; therefore guarding office grows slack and official business gradually grows lax—the blame lies in the provinces and commanderies.\"", idiomatic: "Memorialists repeatedly said, \"Commandery and state recommendations mostly do not follow merit and seniority; therefore officials grow slack in duty and government business gradually grows lax—the blame lies in the provinces and commanderies.\"" },
  { zh: "」有詔下公卿朝臣議。", literal: "\" An edict was sent down for the duke-ministers and court officials to deliberate.", idiomatic: "\" An edict was sent down for the duke-ministers and court officials to deliberate." },
  { zh: "大鴻臚韋彪上議曰：「夫國以簡賢為務，賢以孝行為首，是以求忠臣必於孝子之門。", literal: "Grand Herald Wei Biao submitted a proposal: \"A state takes selecting the worthy as its task; the worthy take filial conduct as foremost—therefore to seek loyal ministers one must go to the doors of filial sons.", idiomatic: "Grand Herald Wei Biao submitted a proposal, \"A state takes selecting the worthy as its task; the worthy take filial conduct as foremost—therefore to seek loyal ministers one must go to the doors of filial sons." },
  { zh: "夫人才行少能相兼，是以孟公綽優於趙、魏老，不可以為滕、薛大夫。", literal: "Now talent and conduct rarely can be joined in one man; therefore Meng Gongchuo was excellent as elder of Zhao and Wei but could not serve as minister of Teng and Xue.", idiomatic: "Talent and conduct are rarely joined in one man; therefore Meng Gongchuo was excellent as elder of Zhao and Wei but could not serve as minister of Teng and Xue." },
  { zh: "忠孝之人，持心近厚；", literal: "Men of loyalty and filial piety hold their hearts near to thickness;", idiomatic: "Men of loyalty and filial piety hold their hearts near to generosity;" },
  { zh: "鍛練之吏，持心近薄。", literal: "officials forged and trained hold their hearts near to thinness.", idiomatic: "officials forged and trained in the law hold their hearts near to harshness." },
  { zh: "士宜以才行為先，不可純以閥閱。", literal: "For scholars, ability and conduct ought to come first; one cannot purely use clan and pedigree.", idiomatic: "For scholars, ability and conduct ought to come first; one cannot rely purely on clan and pedigree." },
  { zh: "然其要歸，在於選二千石。", literal: "Yet its essential point returns to selecting the two-thousand-bushel officials.", idiomatic: "Yet the essential point returns to selecting the two-thousand-bushel officials." },
  { zh: "二千石賢，則貢舉皆得其人矣。", literal: "If the two-thousand-bushel officials are worthy, then recommendations and selections all obtain their men.\"", idiomatic: "If the two-thousand-bushel officials are worthy, then recommendations and selections will all obtain the right men.\"" },
  { zh: "」彪又上疏曰：「天下樞要，在於尚書，尚書之選，豈可不重！", literal: "\" Biao again submitted: \"The realm's pivot and key lies in the Masters of Writing; selection for the Masters of Writing—how can it not be weighty!", idiomatic: "\" Biao again submitted, \"The realm's pivot lies in the Masters of Writing; selection for the Masters of Writing—how can it not be weighty!" },
  { zh: "而間者多從郎官超升此位，雖曉習文法，長於應對，然察察小慧，類無大能。", literal: "Yet recently many have been promoted to this post from Gentleman positions; though they understand written law and excel in reply, they are keen in petty cleverness and mostly lack great capacity.", idiomatic: "Yet recently many have been promoted to this post from Gentleman positions; though they understand written law and excel in reply, they are keen in petty cleverness and mostly lack great capacity." },
  { zh: "宜鑒嗇夫捷急之對，深思絳侯木訥之功也。", literal: "One ought to take warning from the clerk's quick, urgent reply and think deeply on the Marquis of Zhou's wooden, slow merit.\"", idiomatic: "One ought to take warning from the clerk's quick, urgent reply and think deeply on the Marquis of Zhou's slow, wooden merit.\"" },
  { zh: "」帝皆納之。", literal: "\" The emperor adopted all of it.", idiomatic: "\" The emperor adopted all of it." },
  { zh: "彪，賢之玄孫也。", literal: "Biao was the great-great-grandson of Xian.", idiomatic: "Biao was the great-great-grandson of Xian." },
  { zh: "秋，七月，丁未，詔曰：「律云：『掠者唯得榜、笞、立』；", literal: "In autumn, the seventh month, on dingwei, an edict said: \"The statutes say: 'One who tortures may only use cudgeling, flogging, and standing';\"", idiomatic: "In autumn, in the seventh month, on dingwei day, an edict said, \"The statutes say, 'One who tortures may only use cudgeling, flogging, and standing';\"" },
  { zh: "又《令丙》，棰長短有數。", literal: "and Decree C also fixes the long and short of the flogging staff.", idiomatic: "and Decree C also fixes the length of the flogging staff." },
  { zh: "自往者大獄已來，掠者多酷，鑽金贊之屬，慘苦無極。", literal: "Since the great prisons of former times, torturers have mostly been cruel—drilling with metal, driving in pegs, and the like, bitter suffering without limit.", idiomatic: "Since the great prisons of former times, torturers have mostly been cruel—drilling with metal, driving in pegs, and the like, with suffering beyond limit." },
  { zh: "念其痛毒，怵然動心。", literal: "Thinking on their pain and poison, one is startled and moved at heart.", idiomatic: "Thinking on their pain moves the heart to dread." },
  { zh: "宜及秋冬治獄，明為其禁。", literal: "It is fitting that when autumn and winter govern prisons, this be clearly forbidden for them.\"", idiomatic: "It is fitting that in autumn and winter, when prisons are handled, this be clearly forbidden.\"" },
  { zh: "八月，甲子，太尉鄧彪罷，以大司農鄭弘為太尉。", literal: "In the eighth month, on jiazi, Grand Commandant Deng Biao was dismissed and Grand Minister of Agriculture Zheng Hong was made Grand Commandant.", idiomatic: "In the eighth month, on jiazi day, Grand Commandant Deng Biao was dismissed and Grand Minister of Agriculture Zheng Hong was made Grand Commandant." },
  { zh: "癸酉，詔改元。", literal: "On guiyou, an edict changed the era name.", idiomatic: "On guiyou day, an edict changed the era name." },
  { zh: "丁酉，車駕南巡。", literal: "On dingyou, the imperial carriage toured south.", idiomatic: "On dingyou day, the imperial carriage toured south." },
  { zh: "詔：「所經道上郡縣，無得設儲跱。", literal: "An edict said: \"On the roads passed, commanderies and counties must not set up supply depots.\"", idiomatic: "An edict said, \"On the roads the tour passes, commanderies and counties must not set up supply depots.\"" },
  { zh: "命司空自將徒支柱橋樑。", literal: "It ordered the Minister of Works himself to lead laborers to prop bridges and beams.", idiomatic: "It ordered the Minister of Works himself to lead laborers to prop bridges and trestles." },
  { zh: "有遣使奉迎，探知起居，二千石當坐。", literal: "If anyone sends envoys to welcome and inquire after daily health, the two-thousand-shi shall be held liable.", idiomatic: "If anyone sends envoys to welcome the emperor and inquire after his daily health, the responsible two-thousand-shi official shall be punished." },
  { zh: "九月，辛丑，幸章陵；", literal: "In the ninth month, on xinchou, he visited Zhangling;", idiomatic: "In the ninth month, on xinchou day, the emperor visited Zhangling;" },
  { zh: "十月，己未，進幸江陵；", literal: "In the tenth month, on jiwei, he advanced to visit Jiangling;", idiomatic: "In the tenth month, on jiwei day, he advanced to Jiangling;" },
  { zh: "還，幸宛。", literal: "Returning, he visited Wan.", idiomatic: "On the return journey he visited Wan." },
  { zh: "召前臨淮太守宛人朱暉，拜尚書僕射。", literal: "He summoned the former Administrator of Linhuai Zhu Hui, a man of Wan, and appointed him Vice Director of the Masters of Writing.", idiomatic: "He summoned the former Administrator of Linhuai Zhu Hui of Wan and appointed him Vice Director of the Masters of Writing." },
  { zh: "暉在臨淮，有善政，民歌之曰：「強直自遂，南陽朱季，吏畏其威，民懷其惠。", literal: "Hui in Linhuai had good government; the people sang of him, saying: \"Upright and firm, he follows his course—Zhu Ji of Nanyang; clerks fear his awesomeness, the people cherish his grace.", idiomatic: "While Hui was in Linhuai his government was good, and the people sang of him, saying, \"Upright and firm, he follows his course—Zhu Ji of Nanyang; clerks fear his awesomeness, the people cherish his grace." },
  { zh: "」時坐法免，家居，故上召而用之。", literal: "\" At the time he had been dismissed for an offense and was living at home; therefore the emperor summoned and employed him.", idiomatic: "\" He had lately been dismissed for an offense and was living at home, so the emperor summoned and employed him." },
  { zh: "十一月，己丑，車駕還宮。", literal: "In the eleventh month, on jichou, the imperial carriage returned to the palace.", idiomatic: "In the eleventh month, on jichou day, the imperial carriage returned to the palace." },
  { zh: "尚書張林上言：「縣官經用不足，宜自煮鹽，及復修武帝均輸之法。", literal: "Master of Writing Zhang Lin submitted a memorial: \"The government's regular expenditures are insufficient; it is fitting to boil salt in state hands and again restore Emperor Wu's equalizing-transport law.", idiomatic: "Master of Writing Zhang Lin submitted a memorial, saying, \"The government's regular expenditures are insufficient; it is fitting to boil salt under state control and again restore Emperor Wu's equalizing-transport law." },
  { zh: "」朱暉固執以為不可，曰：「均輸之法，與賈販無異，鹽利歸官，則下民窮怨，誠非明主所宜行。", literal: "\" Zhu Hui obstinately held that it could not be done, saying: \"The equalizing-transport law differs in nothing from merchant trafficking; if salt profit returns to the government, the people below will be impoverished and resentful—it is truly not what an enlightened ruler should carry out.", idiomatic: "\" Zhu Hui obstinately held that it could not be done, saying, \"The equalizing-transport law differs in nothing from merchant trafficking; if salt profit returns to the government, the common people will be impoverished and resentful—it is truly not what an enlightened ruler should carry out." },
  { zh: "」帝因發怒切責諸尚書，暉等皆自繫獄。", literal: "\" The Emperor thereupon grew angry and sharply rebuked the Masters of Writing; Hui and the others all bound themselves and entered prison.", idiomatic: "The Emperor thereupon grew angry and sharply rebuked the Masters of Writing; Hui and the others all bound themselves and entered prison." },
  { zh: "三日，詔敕出之，曰：「國家樂聞駁議，黃發無愆。", literal: "After three days an edict ordered them released, saying: \"The state delights to hear rebutting discourse; gray hair is without fault.", idiomatic: "After three days an edict ordered them released, saying, \"The state delights to hear rebutting discourse; the elderly are without fault." },
  { zh: "詔書過耳，何故自系！", literal: "The edict passed your ears—why bind yourselves!", idiomatic: "The edict passed your ears—why bind yourselves!\"" },
  { zh: "」暉因稱病篤，不肯復署議。", literal: "\" Hui thereupon claimed grave illness and would not again sign deliberations.", idiomatic: "Hui thereupon claimed grave illness and would not again sign deliberations." },
  { zh: "尚書令以下惶怖，謂暉曰：「今臨得譴讓，奈何稱病，其禍不細！", literal: "The Director of the Masters of Writing and those below were fearful and alarmed, saying to Hui: \"Now on the verge of rebuke and reproach, how can you claim illness—the calamity will not be slight!", idiomatic: "The Director of the Masters of Writing and those below were fearful and alarmed, saying to Hui, \"You are on the verge of rebuke and reproach—how can you claim illness? The calamity will not be slight!\"" },
  { zh: "」暉曰：「行年八十，蒙恩得在機密，當以死報。", literal: "\" Hui said: \"I have lived eighty years and, receiving grace, attained a post in secrets—I ought to repay with death.", idiomatic: "Hui said, \"I have lived eighty years and, receiving grace, attained a post in secrets—I ought to repay with death." },
  { zh: "若心知不可，而順旨雷同，負臣子之義！", literal: "If in my heart I know it cannot be done yet I follow the intent and echo in agreement, I betray the duty of minister and subject!", idiomatic: "If in my heart I know it cannot be done yet I follow the intent and echo in agreement, I betray the duty of minister and subject!\"" },
  { zh: "今耳目無所聞見，伏待死命。", literal: "Now my ears and eyes hear and see nothing; I lie prostrate awaiting the command of death.", idiomatic: "Now my ears and eyes hear and see nothing; I lie prostrate awaiting death." },
  { zh: "」遂閉口不復言。", literal: "\" He thereupon shut his mouth and spoke no more.", idiomatic: "He thereupon shut his mouth and spoke no more." },
  { zh: "諸尚書不知所為，乃共劾奏暉。", literal: "The Masters of Writing did not know what to do and thereupon jointly memorialized impeaching Hui.", idiomatic: "The Masters of Writing did not know what to do and thereupon jointly memorialized impeaching Hui." },
  { zh: "帝意解，寢其事。", literal: "The Emperor's intent eased and he shelved the matter.", idiomatic: "The Emperor's anger eased and he shelved the matter." },
  { zh: "後數日，詔使直事郎問暉起居，太醫視疾，太官賜食，暉乃起謝；", literal: "Several days later an edict sent an Attending Clerk on duty to inquire after Hui's daily health; the Imperial Physician viewed his illness; the Imperial Commissary bestowed food; Hui then rose to give thanks;", idiomatic: "Several days later an edict sent an Attending Clerk on duty to inquire after Hui's health; the Imperial Physician examined his illness; the Imperial Commissary bestowed food; Hui then rose to give thanks;" },
  { zh: "復賜錢十萬，布百匹，衣十領。", literal: "again bestowed one hundred thousand cash, one hundred bolts of cloth, and ten suits of clothing.", idiomatic: "and again bestowed one hundred thousand cash, one hundred bolts of cloth, and ten suits of clothing." },
  { zh: "魯國孔僖、涿郡崔□因同游太學，相與論：「孝武皇帝，始為天子，崇信聖道，五六年間，號勝文、景；", literal: "Kong Xi of Lu and Cui □ of Zhuo commandery, because they toured the Imperial Academy together, discussed with one another: \"Emperor Xiaowu, when he first became Son of Heaven, honored and trusted the sage Way; within five or six years he was styled superior to Wen and Jing;", idiomatic: "Kong Xi of Lu and Cui □ of Zhuo commandery, having toured the Imperial Academy together, discussed with one another, \"Emperor Wu, when he first became Son of Heaven, honored and trusted the sage Way; within five or six years he was styled superior to Wen and Jing;" },
  { zh: "及後恣己，忘其前善。", literal: "but later he indulged himself and forgot his earlier goodness.", idiomatic: "but later he indulged himself and forgot his earlier virtues.\"" },
  { zh: "」鄰房生梁郁上書，告「駰、僖誹謗先帝，刺譏當世」，事下有司。", literal: "\" A student in the neighboring room, Liang Yu, submitted a memorial reporting \"Yin and Xi slandered the former emperor and stabbed and mocked the present age\"; the matter was sent down to the responsible offices.", idiomatic: "A student in the neighboring room, Liang Yu, submitted a memorial reporting that Yin and Xi had slandered the former emperor and mocked the present age; the matter was sent down to the responsible offices." },
  { zh: "□因詣吏受訊。", literal: "□ thereupon went to the officials to undergo questioning.", idiomatic: "Cui □ thereupon went to the officials to undergo questioning." },
  { zh: "僖以書自訟曰：「凡言誹謗者，謂實無此事而虛加誣之也。", literal: "Xi by letter defended himself, saying: \"Whenever one speaks of slander, it means there was in fact no such matter yet false accusation was heaped on.", idiomatic: "Xi defended himself in writing, saying, \"Whenever one speaks of slander, it means there was in fact no such matter yet a false accusation was heaped on." },
  { zh: "至如孝武皇帝，政之美惡，顯在漢史，坦如日月，是為直說書傳實事，非虛謗也。", literal: "As for Emperor Xiaowu, the beauty and ugliness of his government are manifest in Han histories, open as sun and moon—this is to speak straightly of facts recorded in books and transmissions, not empty slander.", idiomatic: "As for Emperor Wu, the beauty and ugliness of his government are manifest in Han histories, open as sun and moon—this is to speak straightly of facts recorded in books and transmissions, not empty slander." },
  { zh: "夫帝者，為善為惡，天下莫不知，斯皆有以致之，故不可以誅於人也。", literal: "Now an emperor, whether doing good or doing evil—all under Heaven none fail to know; each has what brought it about; therefore one cannot punish people for it.", idiomatic: "An emperor, whether doing good or doing evil—all under Heaven know it; each has what brought it about; therefore one cannot punish people for speaking of it." },
  { zh: "且陛下即位以來，政教未過而德澤有加，天下所具知也，臣等獨何譏刺哉！", literal: "Moreover, since Your Majesty's accession, government and teaching have not transgressed while favor and grace have increased—what all under Heaven fully knows; why should we alone mock and stab!", idiomatic: "Moreover, since Your Majesty's accession, government and teaching have not transgressed while favor and grace have increased—as all under Heaven fully knows; why should we alone mock and criticize!\"" },
  { zh: "假使所非實是，則固應悛改，儻其不當，亦宜含容，又何罪焉！", literal: "Suppose what we criticized were in fact true—then one should indeed repent and reform; if perchance it were not fitting, one should also tolerate and contain—what crime is there!", idiomatic: "Suppose what we criticized were in fact true—then one should indeed repent and reform; if perchance it were not fitting, one should also tolerate it—what crime is there!\"" },
  { zh: "陛下不推原大數，深自為計，徒肆私忌以快其意，臣等受戮，死即死耳，顧天下之人，必回視易慮，以此事窺陛下心，自今以後，苟見不可之事，終莫復言者矣。", literal: "Your Majesty does not trace back to the great reckoning and deeply take thought for yourself, but vainly unleash private jealousy to satisfy your intent—we ministers receive execution; death is death—but I fear the people of all under Heaven will surely turn their gaze and shift their thoughts, and through this matter spy into Your Majesty's heart; from now on, whenever they see what cannot be done, in the end none will speak again.", idiomatic: "Your Majesty does not trace matters to their larger pattern and deeply take thought for yourself, but vainly unleash private jealousy to satisfy your intent—we ministers may be executed, and death is death—but I fear the people of all under Heaven will turn their gaze and shift their thoughts, and through this matter infer Your Majesty's heart; from now on, whenever they see what cannot be done, in the end none will speak again." },
  { zh: "齊桓公親揚其先君之惡以唱管仲，然後群臣得盡其心，今陛下乃欲為十世之武帝遠諱實事，豈不與桓公異哉！", literal: "Duke Huan of Qi personally proclaimed his former ruler's evil to introduce Guan Zhong—only then could the ministers fully give their hearts; now Your Majesty wishes to make distant taboo for Emperor Wu ten generations hence on plain facts—how is this not different from Duke Huan!", idiomatic: "Duke Huan of Qi personally proclaimed his former ruler's evil to introduce Guan Zhong—only then could the ministers fully give their hearts; now Your Majesty wishes to impose distant taboo for Emperor Wu ten generations hence on plain facts—how is this not different from Duke Huan!\"" },
  { zh: "臣恐有司卒然見構，銜恨蒙枉，不得自敘，使後世論者擅以陛下有所比方，寧可復使子孫追掩之乎！", literal: "Your servant fears the authorities will suddenly be made to frame us; bearing resentment we suffer wrong and cannot explain ourselves, causing later generations of discussants presumptuously to compare Your Majesty with something—can one again let descendants pursue and cover it up!", idiomatic: "Your servant fears the authorities will suddenly frame us; bearing resentment we suffer wrong and cannot explain ourselves, causing later generations presumptuously to compare Your Majesty with something—can one again let descendants pursue and cover it up!\"" },
  { zh: "謹詣闕伏待重誅。", literal: "I respectfully come to the gate, prostrate, and await heavy punishment.", idiomatic: "I respectfully come to the gate, prostrate, and await heavy punishment.\"" },
  { zh: "」書奏，帝立詔勿問，拜僖蘭台令史。", literal: "\" When the memorial was submitted, the Emperor at once issued an edict not to inquire and appointed Xi Librarian Clerk of the Orchid Terrace.", idiomatic: "When the memorial was submitted, the Emperor at once issued an edict not to inquire and appointed Xi Librarian Clerk of the Orchid Terrace." },
  { zh: "十二月，壬子，詔：「前以妖惡禁錮三屬者，一皆蠲除之，但不得在宿衛而已。", literal: "In the twelfth month, on renzi, an edict said: \"Formerly, because of malign portents, those confined through three degrees of kin were all remitted and cleared, only they may not serve in the palace guard.", idiomatic: "In the twelfth month, on renzi day, an edict said, \"Formerly, because of malign portents, those confined through three degrees of kin were all remitted and cleared, only they may not serve in the palace guard.\"" },
  { zh: "廬江毛義，東平鄭均，皆以行義稱於鄉里。", literal: "Mao Yi of Lujiang and Zheng Jun of Dongping were both styled for conduct and righteousness in their villages and hamlets.", idiomatic: "Mao Yi of Lujiang and Zheng Jun of Dongping were both famed in their villages for conduct and righteousness." },
  { zh: "南陽張奉慕義名，往候之，坐定而府檄適至，以義守安陽令，以捧檄而入，喜動顏色，奉心賤之，辭去。", literal: "Zhang Feng of Nanyang admired Yi's name and went to visit him; when they had sat and settled, a commandery dispatch happened to arrive appointing Yi to hold the magistracy of Anyang; holding the dispatch he entered, joy moving his countenance; Feng in his heart despised him and took leave.", idiomatic: "Zhang Feng of Nanyang admired Yi's reputation and went to visit him; when they had sat down, a commandery dispatch happened to arrive appointing Yi magistrate of Anyang; holding the dispatch he entered, joy moving his countenance; Feng despised him in his heart and took his leave." },
  { zh: "後義母死。", literal: "Later Yi's mother died.", idiomatic: "Later Yi's mother died." },
  { zh: "征辟皆不至，奉乃歎曰：「賢者固不可測。", literal: "Summons and appointments all he did not accept; Feng then sighed, saying: \"A worthy man truly cannot be measured.", idiomatic: "Summons and appointments he declined them all; Feng then sighed, saying, \"A worthy man truly cannot be measured." },
  { zh: "往日之喜，乃為親屈也。", literal: "His former joy was yielding for his kin.", idiomatic: "His former joy was yielding for his parents.\"" },
  { zh: "」均兄為縣吏，頗受禮遺，均諫不聽，乃脫身為傭，歲餘得錢帛，歸以與兄曰：「物盡可復得，為吏坐臧，終身捐棄。", literal: "\" Jun's elder brother was a county clerk and quite accepted gifts and presents; Jun remonstrated but he would not listen; Jun thereupon left his person to become a hired laborer; after more than a year he obtained cash and silks, returned and gave them to his brother, saying: \"Goods exhausted can be obtained again; as a clerk sitting in corruption, one is cast off for life.", idiomatic: "Jun's elder brother was a county clerk and quite accepted gifts and presents; Jun remonstrated but he would not listen; Jun thereupon hired himself out as a laborer; after more than a year he obtained cash and silks, returned and gave them to his brother, saying, \"Goods exhausted can be obtained again; as a clerk convicted of corruption, one is cast off for life." },
  { zh: "」兄感其言，遂為廉潔。", literal: "\" The brother was moved by his words and thereupon became honest and clean.", idiomatic: "His brother was moved by his words and thereupon became honest and clean." },
  { zh: "均仕為尚書，免歸。", literal: "Jun served as Master of Writing and was dismissed, returning home.", idiomatic: "Jun served as Master of Writing, was dismissed, and returned home." },
  { zh: "帝下詔褒寵義、均，賜谷各千斛，常以八月長吏差問起居，加賜羊酒。", literal: "The Emperor issued an edict praising and favoring Yi and Jun, bestowing on each one thousand hu of grain; regularly in the eighth month senior officials were sent in turn to inquire after their health, with added gifts of sheep and wine.", idiomatic: "The Emperor issued an edict praising and favoring Yi and Jun, bestowing on each one thousand hu of grain; regularly in the eighth month senior officials were sent in turn to inquire after their health, with added gifts of sheep and wine." },
  { zh: "武威太守孟雲上言：「北匈奴復願與吏民合市。", literal: "Administrator of Wuwei Meng Yun submitted a memorial: \"The Northern Xiongnu again wish to hold joint markets with officials and people.", idiomatic: "Administrator of Wuwei Meng Yun submitted a memorial, saying, \"The Northern Xiongnu again wish to hold joint markets with officials and people." },
  { zh: "」詔許之。", literal: "\" An edict permitted it.", idiomatic: "An edict permitted it." },
  { zh: "北匈奴大且渠伊莫訾王等驅牛馬萬餘頭來與漢交易，南單于遣輕騎出上郡鈔之，大獲而還。", literal: "The Northern Xiongnu Grand Commandant Yimoze and others drove more than ten thousand head of cattle and horses to trade with Han; the Southern Chanyu sent light horse out of Shang commandery to raid them and returned with great booty.", idiomatic: "The Northern Xiongnu Grand Commandant Yimoze and others drove more than ten thousand head of cattle and horses to trade with Han; the Southern Chanyu sent light cavalry out of Shang commandery to raid them and returned with great booty." },
  { zh: "帝復遣假司馬和恭等將兵八百人詣班超，超因發疏勒、於窴兵擊莎車。", literal: "The Emperor again sent Acting Major He Gong and others leading eight hundred troops to Ban Chao; Chao thereupon mobilized Shule and Yutian troops to attack Shache.", idiomatic: "The Emperor again sent Acting Major He Gong and others leading eight hundred troops to Ban Chao; Chao thereupon mobilized Shule and Yutian troops to attack Shache." },
  { zh: "莎車以賂誘疏勒王忠，忠遂反，從之，西保烏即城。", literal: "Shache by bribes enticed King Zhong of Shule; Zhong thereupon rebelled, followed them, and westward held Wuji city.", idiomatic: "Shache by bribes enticed King Zhong of Shule; Zhong thereupon rebelled, followed them, and westward held Wuji city." },
  { zh: "超乃更立其府丞成大為疏勒王，悉發其不反者以攻忠。", literal: "Chao thereupon replaced him and established his bureau assistant Cheng Da as king of Shule, fully mobilizing those who had not rebelled to attack Zhong.", idiomatic: "Chao thereupon replaced him and established his bureau assistant Cheng Da as king of Shule, fully mobilizing those who had not rebelled to attack Zhong." },
  { zh: "使人說康居王執忠以歸其國，烏即城遂降。", literal: "He sent someone to persuade the king of Kangju to seize Zhong and return him to his state; Wuji city thereupon surrendered.", idiomatic: "He sent someone to persuade the king of Kangju to seize Zhong and return him to his state; Wuji city thereupon surrendered." },
  { zh: "category:資治通鑑", literal: "—", idiomatic: "—" }
];
